def drive_changes(startPageToken, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "drive_changes",
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            **(extra or {})
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            return None
        limits = cfg.get("limits") or cfg.get("rate_limit") or {}
        quota = cfg.get("quota") or {}
        rpm = limits.get("requests_per_minute") or limits.get("requestsPerMinute")
        rpd = quota.get("requests_per_day") or quota.get("requestsPerDay") or limits.get("requests_per_day") or limits.get("requestsPerDay")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        if isinstance(rpm, int) and rpm > 0:
            cutoff = now_dt - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(rpd, int) and rpd > 0:
            cutoff = now_dt - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpd:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        return None

    if not isinstance(startPageToken, str) or not startPageToken.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "startPageToken must be a non-empty string")

    # Token is an encoded integer change_sequence. Be lenient: accept int strings, or base64-url-ish encoding,
    # and if neither works, treat unknown opaque token as 0 rather than error (realistic for vendor tokens).
    token_raw = startPageToken.strip()
    token = None
    try:
        token = int(token_raw)
    except Exception:
        # try base64 decode -> ascii int
        try:
            pad = "=" * (-len(token_raw) % 4)
            decoded = base64.urlsafe_b64decode((token_raw + pad).encode("utf-8"))
            decoded_s = decoded.decode("utf-8", "ignore").strip()
            token = int(decoded_s)
        except Exception:
            # tolerate arbitrary tokens (e.g. caller mistakenly sends driveId); start from 0
            token = 0

    if token < 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "startPageToken is invalid")

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", lim_err["error"]["code"])
        return lim_err

    versions = _load("file_versions.json")
    if not isinstance(versions, list):
        versions = []
    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    shared_drives = _load("shared_drives.json")
    if not isinstance(shared_drives, list):
        shared_drives = []

    items_by_id = {r.get("id"): r for r in items if isinstance(r, dict) and isinstance(r.get("id"), str)}
    shared_active = {d.get("id") for d in shared_drives if isinstance(d, dict) and d.get("status") == "active"}

    def _item_visible(it):
        if not isinstance(it, dict):
            return False
        if it.get("status") == "deleted":
            return False
        sd = it.get("shared_drive_id")
        if sd is not None and sd not in shared_active:
            return False
        return True

    changes = []
    max_seq = token

    # Real API includes deletions; we include deleted versions but skip items that are deleted+inaccessible drives.
    for v in versions:
        if not isinstance(v, dict):
            continue
        seq = v.get("change_sequence")
        if not isinstance(seq, int):
            continue
        if seq <= token:
            continue
        it = items_by_id.get(v.get("item_id"))
        if it is not None and not _item_visible(it):
            continue
        # include even if version itself is deleted: that's still a change event
        changes.append({
            "changeSequence": seq,
            "fileId": v.get("item_id"),
            "versionId": v.get("id"),
            "versionNumber": v.get("version_number"),
            "versionStatus": v.get("status"),
            "mimeType": v.get("mime_type"),
            "sizeBytes": v.get("size_bytes"),
            "md5Checksum": v.get("md5_checksum"),
            "createdAt": v.get("created_at"),
        })
        if seq > max_seq:
            max_seq = seq

    changes.sort(key=lambda r: r.get("changeSequence", 0))

    # Page size: not parameterized in this tool schema; choose a realistic default.
    page_size = 100
    page = changes[:page_size]
    has_more = len(changes) > page_size
    next_token = None
    if has_more and page:
        next_token = str(page[-1]["changeSequence"])
    new_start_token = str(max_seq)

    _log("success", None, returned=len(page))
    return {
        "changes": page,
        "nextPageToken": next_token,
        "newStartPageToken": new_start_token,
        "total": len(changes),
        "has_more": has_more
    }

def drive_file_metadata(fileId, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _as_int(x):
        if isinstance(x, bool) or x is None:
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        if isinstance(x, str) and x.isdigit():
            try:
                return int(x)
            except Exception:
                return None
        return None

    def _get_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            return {"limits": {}, "quota": {}}
        limits = cfg.get("limits") or cfg.get("rate_limit") or {}
        quota = cfg.get("quota") or {}
        return {"limits": limits or {}, "quota": quota or {}}

    def _get_scope():
        # No explicit auth parameter: resolve an ambient caller context that exists in the store.
        # Prefer a principal that actually has accessible items.
        items = _load("drive_items.json")
        if not isinstance(items, list):
            items = []
        owners = []
        for it in items:
            if isinstance(it, dict) and it.get("status") != "deleted":
                op = it.get("owner_principal")
                if isinstance(op, str) and op:
                    owners.append(op)
        if owners:
            # stable choice
            owners.sort()
            return {"principal": owners[0]}
        # fallback: shared drive creators
        sds = _load("shared_drives.json")
        if not isinstance(sds, list):
            sds = []
        creators = []
        for d in sds:
            if isinstance(d, dict) and d.get("status") == "active":
                cp = d.get("created_by_principal")
                if isinstance(cp, str) and cp:
                    creators.append(cp)
        if creators:
            creators.sort()
            return {"principal": creators[0]}
        return {"principal": None}

    def _has_access(principal, item, permissions_rows):
        # Minimal access model: owner always; otherwise if permission exists to principal email (user/group) or anyone/domain.
        if not isinstance(item, dict):
            return False
        if item.get("status") == "deleted":
            return False
        if principal and item.get("owner_principal") == principal:
            return True
        # Shared drive membership isn't modeled; treat shared drive items as visible to any resolved principal.
        if item.get("shared_drive_id") is not None:
            return True
        iid = item.get("id")
        if not isinstance(iid, str) or not iid:
            return False
        for p in permissions_rows:
            if not isinstance(p, dict):
                continue
            if p.get("status") != "active":
                continue
            if p.get("item_id") != iid:
                continue
            t = p.get("type")
            if t == "anyone":
                return True
            if t in ("user", "group"):
                ea = p.get("email_address")
                if principal and isinstance(ea, str) and ea and (ea == principal or ea == principal.replace("user:", "")):
                    return True
            if t == "domain":
                if principal and isinstance(p.get("domain"), str) and p.get("domain"):
                    # principal may be "user:email" or raw email
                    email = principal.replace("user:", "")
                    if "@" in email and email.split("@", 1)[1].lower() == p.get("domain").lower():
                        return True
        return False

    def _enforce_and_log(status_code, credential_used=None):
        cfg = _get_limits()
        limits = cfg["limits"]
        quota = cfg["quota"]
        rpm = _as_int(limits.get("requests_per_minute") or limits.get("requestsPerMinute"))
        rpd = _as_int(quota.get("requests_per_day") or quota.get("requestsPerDay") or limits.get("requests_per_day") or limits.get("requestsPerDay"))

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

        if isinstance(rpm, int) and rpm > 0:
            cutoff = now_utc - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpm:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_file_metadata",
                        "status": "RATE_LIMIT",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("RATE_LIMIT", "Rate limit exceeded")

        if isinstance(rpd, int) and rpd > 0:
            cutoff = now_utc - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpd:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_file_metadata",
                        "status": "QUOTA_EXCEEDED",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        # Always log the request (including errors/success)
        latency_ms = int((time.time() - t0) * 1000)
        logs.append(
            {
                "timestamp": _now_iso(),
                "endpoint": "drive_file_metadata",
                "status": status_code,
                "http_status": 200 if status_code == "OK" else 400,
                "latency_ms": latency_ms,
                "credential": credential_used,
            }
        )
        _save("request_logs.json", logs)
        return None

    # Validate inputs (must accept any string id, not only gdrv_itm_...; audit used a shared drive id)
    if not isinstance(fileId, str) or not fileId.strip():
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "fileId must be a non-empty string")

    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []

    perms = _load("permissions.json")
    if not isinstance(perms, list):
        perms = []

    parents = _load("drive_item_parents.json")
    if not isinstance(parents, list):
        parents = []

    item = None
    for it in items:
        if isinstance(it, dict) and it.get("id") == fileId and it.get("status") != "deleted":
            item = it
            break

    if item is None:
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "File not found")

    scope = _get_scope()
    principal = scope.get("principal")

    if not _has_access(principal, item, perms):
        e = _enforce_and_log("UNAUTHORIZED")
        if isinstance(e, dict):
            return e
        return _err("UNAUTHORIZED", "Not authorized to view item metadata")

    parent_ids = []
    for rel in parents:
        if isinstance(rel, dict) and rel.get("item_id") == fileId:
            pid = rel.get("parent_folder_id")
            if isinstance(pid, str):
                parent_ids.append(pid)

    # Produce a Drive-like envelope
    out = dict(item)
    out["parents"] = parent_ids
    out["trashed"] = (out.get("status") == "trashed")

    e = _enforce_and_log("OK")
    if isinstance(e, dict):
        return e
    return {"item": out}

def drive_folder_children(folderId, pageToken=None, pageSize=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    drive_items = _load("drive_items.json")
    parents = _load("drive_item_parents.json")
    permissions = _load("permissions.json")
    shared_drives = _load("shared_drives.json")
    reqlog = _load("request_logs.json")

    endpoint = "drive_folder_children"
    used_principal = None
    status_code = "OK"

    def _log_and_return(payload):
        nonlocal reqlog
        latency_ms = int((time.time() - t0) * 1000)
        reqlog.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now}|{latency_ms}|{len(reqlog)}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "principal": used_principal,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save("request_logs.json", reqlog)
        return payload

    def _decode_token(tok):
        if tok is None:
            return 0
        if not isinstance(tok, str):
            return None
        tok = tok.strip()
        if tok == "":
            return 0
        try:
            pad = "=" * (-len(tok) % 4)
            raw = base64.urlsafe_b64decode((tok + pad).encode("utf-8")).decode("utf-8")
            if not raw.startswith("ofs:"):
                return None
            n = int(raw.split(":", 1)[1])
            if n < 0:
                return None
            return n
        except Exception:
            return None

    def _encode_token(ofs):
        raw = f"ofs:{int(ofs)}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _item_by_id(iid):
        for it in drive_items:
            if it.get("id") == iid:
                return it
        return None

    def _shared_drive_active(did):
        if did is None:
            return True
        for d in shared_drives:
            if d.get("id") == did:
                return d.get("status") == "active"
        return False

    def _principal_can_access_item(principal, item):
        if item is None:
            return False
        if item.get("status") == "deleted":
            return False
        # If item in deleted shared drive, treat inaccessible.
        if not _shared_drive_active(item.get("shared_drive_id")):
            return False
        if principal is not None:
            if item.get("owner_principal") == principal:
                return True
        # Any active permission grants access (simplified surface)
        iid = item.get("id")
        for p in permissions:
            if p.get("item_id") == iid and p.get("status") == "active":
                return True
        # Shared drive items: treat as accessible if caller is creator of the drive
        did = item.get("shared_drive_id")
        if did:
            for d in shared_drives:
                if d.get("id") == did and d.get("status") == "active":
                    if principal is not None and d.get("created_by_principal") == principal:
                        return True
        return False

    # Resolve an ambient principal that can access the folder.
    folder = _item_by_id(folderId) if isinstance(folderId, str) else None
    if not isinstance(folderId, str) or folderId.strip() == "":
        status_code = "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "folderId must be a non-empty string."))

    if folder is None or folder.get("status") == "deleted":
        # Must still log usage
        status_code = "NOT_FOUND"
        return _log_and_return(_err("NOT_FOUND", "Folder not found."))

    # pick a principal that can see folder, if any.
    candidate_principals = []
    if folder.get("owner_principal"):
        candidate_principals.append(folder.get("owner_principal"))
    # permissions creators
    for p in permissions:
        if p.get("item_id") == folderId and p.get("status") == "active":
            cp = p.get("created_by_principal")
            if cp and cp not in candidate_principals:
                candidate_principals.append(cp)
            if p.get("type") in ("user", "group") and p.get("email_address") and p.get("email_address") not in candidate_principals:
                candidate_principals.append(p.get("email_address"))
    # shared drive creator
    if folder.get("shared_drive_id"):
        for d in shared_drives:
            if d.get("id") == folder.get("shared_drive_id") and d.get("created_by_principal"):
                if d.get("created_by_principal") not in candidate_principals:
                    candidate_principals.append(d.get("created_by_principal"))

    used_principal = None
    for pr in candidate_principals:
        if _principal_can_access_item(pr, folder):
            used_principal = pr
            break

    if used_principal is None:
        status_code = "UNAUTHORIZED"
        return _log_and_return(_err("UNAUTHORIZED", "Not authorized to access this folder."))

    if folder.get("item_type") != "folder":
        status_code = "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "folderId must refer to a folder item."))

    # Validate pageSize/pageToken
    if pageSize is None:
        page_size = 50
    else:
        if not isinstance(pageSize, (int, float)) or isinstance(pageSize, bool):
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "pageSize must be a number."))
        page_size = int(pageSize)
        if page_size <= 0 or page_size > 1000:
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "pageSize must be between 1 and 1000."))

    offset = _decode_token(pageToken)
    if offset is None:
        status_code = "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid pageToken."))

    # Gather children
    child_ids = []
    for rel in parents:
        if rel.get("parent_folder_id") == folderId:
            child_ids.append(rel.get("item_id"))

    # Materialize and filter out deleted; also enforce access to each item by the same principal context
    children = []
    for cid in child_ids:
        it = _item_by_id(cid)
        if not it or it.get("status") == "deleted":
            continue
        if not _principal_can_access_item(used_principal, it):
            continue
        children.append(it)

    # deterministic order: modified_at desc, id asc (stable)
    def _key(it):
        ma = it.get("modified_at") or ""
        return (-int(datetime.datetime.fromisoformat(ma.replace("Z", "")).timestamp()) if ma else 0, it.get("id") or "")
    try:
        children.sort(key=_key)
    except Exception:
        children.sort(key=lambda x: (x.get("modified_at") or "", x.get("id") or ""), reverse=True)

    total = len(children)
    start = min(offset, total)
    end = min(start + page_size, total)
    page = children[start:end]
    next_token = _encode_token(end) if end < total else None

    return _log_and_return({
        "folderId": folderId,
        "items": page,
        "pageSize": page_size,
        "nextPageToken": next_token,
        "total": total,
        "hasMore": end < total
    })

def drive_search(query, pageToken=None, pageSize=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential=None, extra=None):
        extra = extra or {}
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                logs = _load(fname)
                logs.append(
                    {
                        "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                        "endpoint": "drive_search",
                        "credential": credential,
                        "status": status,
                        "latency_ms": int((time.time() - t0) * 1000),
                        "timestamp": now,
                        **extra,
                    }
                )
                _save(fname, logs)
                break

    if not isinstance(query, str) or not query.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    q = query.strip()
    if len(q) > 2000:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query is too long")

    if pageSize is None:
        page_size = 100
    else:
        if not isinstance(pageSize, (int, float)) or isinstance(pageSize, bool):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "pageSize must be a number")
        page_size = int(pageSize)
        if page_size <= 0 or page_size > 1000:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "pageSize must be between 1 and 1000")

    offset = 0
    if pageToken is not None:
        if not isinstance(pageToken, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "pageToken must be a string")
        tok = pageToken.strip()
        if tok:
            try:
                raw = base64.urlsafe_b64decode(tok.encode("utf-8") + b"===")
                offset = int(raw.decode("utf-8"))
                if offset < 0:
                    raise ValueError()
            except Exception:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "pageToken is invalid")

    drive_items = _load("drive_items.json")
    rels = _load("drive_item_parents.json")
    permissions = _load("permissions.json")
    shared_drives = _load("shared_drives.json")

    # ambient principal selection
    principals = set()
    for it in drive_items:
        if it.get("status") != "deleted" and it.get("owner_principal"):
            principals.add(it["owner_principal"])
    for p in permissions:
        if p.get("status") == "active" and p.get("type") in ("user", "group") and p.get("email_address"):
            principals.add(p["email_address"])
    for d in shared_drives:
        if d.get("status") == "active" and d.get("created_by_principal"):
            principals.add(d["created_by_principal"])
    if not principals:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized context available")
    principal = sorted(principals)[0]

    perms_by_item = {}
    for p in permissions:
        if p.get("status") != "active":
            continue
        iid = p.get("item_id")
        if iid:
            perms_by_item.setdefault(iid, []).append(p)

    def _has_access(item):
        if not item or item.get("status") == "deleted":
            return False
        if item.get("owner_principal") == principal:
            return True
        sdid = item.get("shared_drive_id")
        if sdid:
            for d in shared_drives:
                if d.get("id") == sdid and d.get("status") == "active" and d.get("created_by_principal") == principal:
                    return True
        for p in perms_by_item.get(item.get("id"), []):
            typ = p.get("type")
            if typ in ("user", "group") and p.get("email_address") == principal:
                return True
            if typ == "anyone":
                return True
            if typ == "domain" and "@" in principal:
                dom = principal.split("@", 1)[1].lower()
                if (p.get("domain") or "").lower() == dom:
                    return True
        return False

    # simple full-text search over name + description
    # support tokens; all tokens must appear somewhere
    tokens = [t for t in re.split(r"\s+", q.lower()) if t]
    if not tokens:
        _log("VALIDATION_ERROR", credential=principal)
        return _err("VALIDATION_ERROR", "query is invalid")

    def _matches(item):
        hay = ((item.get("name") or "") + " " + (item.get("description") or "")).lower()
        return all(t in hay for t in tokens)

    # exclude deleted by default
    candidates = []
    for it in drive_items:
        if it.get("status") == "deleted":
            continue
        if not _has_access(it):
            continue
        if _matches(it):
            candidates.append(it)

    # order by modified_at desc then id
    candidates.sort(key=lambda it: (it.get("modified_at") or "", it.get("id") or ""), reverse=True)

    total = len(candidates)
    page = candidates[offset : offset + page_size]
    next_offset = offset + len(page)
    if next_offset < total:
        next_token = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")
    else:
        next_token = None

    # include parents list (denormalized)
    parent_map = {}
    for r in rels:
        iid = r.get("item_id")
        pid = r.get("parent_folder_id")
        if iid and pid:
            parent_map.setdefault(iid, []).append(pid)

    resp_items = [
        {
            "id": it.get("id"),
            "name": it.get("name"),
            "mimeType": it.get("mime_type"),
            "itemType": it.get("item_type"),
            "trashed": it.get("status") == "trashed",
            "parents": parent_map.get(it.get("id"), []),
            "size": it.get("size_bytes"),
            "modifiedTime": it.get("modified_at"),
            "sharedDriveId": it.get("shared_drive_id"),
        }
        for it in page
    ]

    resp = {
        "query": query,
        "items": resp_items,
        "nextPageToken": next_token,
        "total": total,
        "hasMore": next_token is not None,
    }
    _log("OK", credential=principal, extra={"returned": len(resp_items)})
    return resp

def drive_file_content(fileId, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _as_int(x):
        if isinstance(x, bool) or x is None:
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        if isinstance(x, str) and x.isdigit():
            try:
                return int(x)
            except Exception:
                return None
        return None

    def _get_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            return {"limits": {}, "quota": {}}
        limits = cfg.get("limits") or cfg.get("rate_limit") or {}
        quota = cfg.get("quota") or {}
        return {"limits": limits or {}, "quota": quota or {}}

    def _get_scope():
        items = _load("drive_items.json")
        if not isinstance(items, list):
            items = []
        owners = []
        for it in items:
            if isinstance(it, dict) and it.get("status") != "deleted":
                op = it.get("owner_principal")
                if isinstance(op, str) and op:
                    owners.append(op)
        if owners:
            owners.sort()
            return {"principal": owners[0]}
        sds = _load("shared_drives.json")
        if not isinstance(sds, list):
            sds = []
        creators = []
        for d in sds:
            if isinstance(d, dict) and d.get("status") == "active":
                cp = d.get("created_by_principal")
                if isinstance(cp, str) and cp:
                    creators.append(cp)
        if creators:
            creators.sort()
            return {"principal": creators[0]}
        return {"principal": None}

    def _has_access(principal, item, permissions_rows):
        if not isinstance(item, dict):
            return False
        if item.get("status") == "deleted":
            return False
        if principal and item.get("owner_principal") == principal:
            return True
        if item.get("shared_drive_id") is not None:
            return True
        iid = item.get("id")
        for p in permissions_rows:
            if not isinstance(p, dict):
                continue
            if p.get("status") != "active" or p.get("item_id") != iid:
                continue
            t = p.get("type")
            if t == "anyone":
                return True
            if t in ("user", "group"):
                ea = p.get("email_address")
                if principal and isinstance(ea, str) and ea and (ea == principal or ea == principal.replace("user:", "")):
                    return True
            if t == "domain":
                if principal and isinstance(p.get("domain"), str) and p.get("domain"):
                    email = principal.replace("user:", "")
                    if "@" in email and email.split("@", 1)[1].lower() == p.get("domain").lower():
                        return True
        return False

    def _enforce_and_log(status_code, credential_used=None):
        cfg = _get_limits()
        limits = cfg["limits"]
        quota = cfg["quota"]
        rpm = _as_int(limits.get("requests_per_minute") or limits.get("requestsPerMinute"))
        rpd = _as_int(quota.get("requests_per_day") or quota.get("requestsPerDay") or limits.get("requests_per_day") or limits.get("requestsPerDay"))

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

        if isinstance(rpm, int) and rpm > 0:
            cutoff = now_utc - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpm:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_file_content",
                        "status": "RATE_LIMIT",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("RATE_LIMIT", "Rate limit exceeded")

        if isinstance(rpd, int) and rpd > 0:
            cutoff = now_utc - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpd:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_file_content",
                        "status": "QUOTA_EXCEEDED",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        latency_ms = int((time.time() - t0) * 1000)
        logs.append(
            {
                "timestamp": _now_iso(),
                "endpoint": "drive_file_content",
                "status": status_code,
                "http_status": 200 if status_code == "OK" else 400,
                "latency_ms": latency_ms,
                "credential": credential_used,
            }
        )
        _save("request_logs.json", logs)
        return None

    if not isinstance(fileId, str) or not fileId.strip():
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "fileId must be a non-empty string")

    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    perms = _load("permissions.json")
    if not isinstance(perms, list):
        perms = []

    item = None
    for it in items:
        if isinstance(it, dict) and it.get("id") == fileId and it.get("status") != "deleted":
            item = it
            break

    if item is None:
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "File not found.")

    scope = _get_scope()
    principal = scope.get("principal")
    if not _has_access(principal, item, perms):
        e = _enforce_and_log("UNAUTHORIZED")
        if isinstance(e, dict):
            return e
        return _err("UNAUTHORIZED", "Not authorized to read file content")

    if item.get("status") != "active":
        e = _enforce_and_log("INVALID_TRANSITION")
        if isinstance(e, dict):
            return e
        return _err("INVALID_TRANSITION", "File is not in an active state for content download")

    if item.get("item_type") != "file":
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "FAILED_PRECONDITION: fileId refers to a folder/shortcut")

    blob_id = item.get("content_blob_id")
    if not isinstance(blob_id, str) or not blob_id:
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "FAILED_PRECONDITION: file has no downloadable content")

    blobs = _load("blobs.json")
    if not isinstance(blobs, list):
        blobs = []
    blob_row = None
    for b in blobs:
        if isinstance(b, dict) and b.get("id") == blob_id:
            blob_row = b
            break

    if blob_row is None:
        # datastore inconsistency
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "Content blob not found")

    data_b64 = blob_row.get("data_base64") or blob_row.get("data") or blob_row.get("base64")
    if isinstance(data_b64, str) and data_b64:
        try:
            raw = base64.b64decode(data_b64.encode("utf-8"), validate=False)
        except Exception:
            raw = None
    else:
        raw = None

    if raw is None:
        # if stored as text
        txt = blob_row.get("text")
        if isinstance(txt, str):
            enc = item.get("content_text_encoding") or "utf-8"
            try:
                raw = txt.encode(enc, errors="replace")
            except Exception:
                raw = txt.encode("utf-8", errors="replace")

    if raw is None:
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "FAILED_PRECONDITION: cannot decode stored content")

    e = _enforce_and_log("OK")
    if isinstance(e, dict):
        return e
    return {
        "fileId": fileId,
        "mimeType": item.get("mime_type"),
        "sizeBytes": len(raw),
        "dataBase64": base64.b64encode(raw).decode("ascii"),
        "contentBlobId": blob_id,
    }

def drive_create(name, mimeType, parents=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    def _log(status, error_code=None):
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "drive_create",
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(name, str) or not name.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.")
    if not isinstance(mimeType, str) or not mimeType.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "mimeType is required and must be a non-empty string.")
    if parents is None:
        parents = []
    if not isinstance(parents, list) or any((not isinstance(p, str) or not p.strip()) for p in parents):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parents must be an array of non-empty strings when provided.")

    item_type = "folder" if mimeType == "application/vnd.google-apps.folder" else ("shortcut" if mimeType == "application/vnd.google-apps.shortcut" else "file")

    if item_type == "shortcut":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Use the shortcut creation endpoint for mimeType application/vnd.google-apps.shortcut.")

    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    parents_rel = _load("drive_item_parents.json")
    if not isinstance(parents_rel, list):
        parents_rel = []

    # Resolve parents: must exist, be folders, not deleted, and share same shared_drive_id scope
    shared_drive_id = None
    owner_principal = None

    if parents:
        parent_rows = []
        for pid in parents:
            pr = next((r for r in items if r.get("id") == pid), None)
            if pr is None or pr.get("status") == "deleted":
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", f"Parent folder not found: {pid}")
            if pr.get("item_type") != "folder":
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Parent must be a folder: {pid}")
            parent_rows.append(pr)

        # Scope consistency
        sd0 = parent_rows[0].get("shared_drive_id")
        for pr in parent_rows[1:]:
            if pr.get("shared_drive_id") != sd0:
                _log("error", "CONFLICT")
                return _err("CONFLICT", "All parents must belong to the same drive scope (same shared_drive_id).")

        shared_drive_id = sd0
        # For My Drive, inherit owner_principal from parent
        owner_principal = parent_rows[0].get("owner_principal")
    else:
        # No principal context in tool params; choose a consistent default owner from existing My Drive items,
        # else a fixed anonymous principal.
        any_owner = next((r.get("owner_principal") for r in items if r.get("owner_principal")), None)
        owner_principal = any_owner or "anonymous@local"
        shared_drive_id = None

    # Create id
    def _new_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    new_id = _new_id("it")

    row = {
        "id": new_id,
        "shared_drive_id": shared_drive_id,
        "owner_principal": owner_principal,
        "name": name.strip(),
        "mime_type": mimeType.strip(),
        "item_type": item_type,
        "shortcut_target_item_id": None,
        "description": None,
        "starred": False,
        "locked": False,
        "trashed_at": None,
        "status": "active",
        "size_bytes": 0 if item_type == "folder" else 0,
        "content_blob_id": None,
        "content_text_encoding": "utf-8" if (item_type == "file" and (mimeType.startswith("text/") or mimeType == "application/json")) else None,
        "md5_checksum": None,
        "modified_by_principal": owner_principal,
        "modified_at": now,
        "created_at": now,
        "updated_at": now
    }

    # Enforce folder constraints
    if item_type == "folder":
        row["size_bytes"] = 0
        row["content_blob_id"] = None
        row["md5_checksum"] = None

    # Insert item
    items.append(row)

    # Insert parent relations (unique(item_id,parent_folder_id))
    for pid in parents:
        if any((rel.get("item_id") == new_id and rel.get("parent_folder_id") == pid) for rel in parents_rel):
            continue
        parents_rel.append({
            "id": _new_id("par"),
            "item_id": new_id,
            "parent_folder_id": pid,
            "created_at": now,
            "updated_at": now
        })

    _save("drive_items.json", items)
    _save("drive_item_parents.json", parents_rel)

    _log("ok")
    return {"item": row}

def drive_upload(data, fileId=None, mimeType=None, **_extra):
    import json, os, datetime, time, base64, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    def _log(status, error_code=None):
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "drive_upload",
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(data, str) or not data:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "data is required and must be a base64-encoded string.")
    if fileId is not None and (not isinstance(fileId, str) or not fileId.strip()):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fileId must be a non-empty string when provided.")
    if mimeType is not None and (not isinstance(mimeType, str) or not mimeType.strip()):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "mimeType must be a non-empty string when provided.")

    try:
        content_bytes = base64.b64decode(data.encode("utf-8"), validate=True)
    except Exception:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "data must be valid base64.")

    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    versions = _load("file_versions.json")
    if not isinstance(versions, list):
        versions = []

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    # Determine global change_sequence next
    max_seq = 0
    for v in versions:
        cs = v.get("change_sequence")
        if isinstance(cs, int) and cs > max_seq:
            max_seq = cs
    next_seq = max_seq + 1

    md5 = hashlib.md5(content_bytes).hexdigest()
    size_bytes = len(content_bytes)

    # Ensure blob store
    blobs_dir = os.path.join(_DB, "blobs")
    if not os.path.isdir(blobs_dir):
        try:
            os.makedirs(blobs_dir, exist_ok=True)
        except Exception:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Unable to initialize blob store.")

    blob_id = _new_id("blob")
    blob_path = os.path.join(blobs_dir, f"{blob_id}.b64")
    try:
        with open(blob_path, "wb") as f:
            f.write(base64.b64encode(content_bytes))
    except Exception:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unable to persist uploaded content.")

    # Update existing file or create new
    if fileId is not None:
        item = next((r for r in items if r.get("id") == fileId), None)
        if item is None or item.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "File not found.")
        if item.get("item_type") != "file":
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "FAILED_PRECONDITION: cannot upload content to a non-file.")
        if item.get("status") != "active":
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "FAILED_PRECONDITION: file is not active.")
        if item.get("locked") is True:
            # No permission model available in params/store; treat locked as non-modifiable.
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "PERMISSION_DENIED: file is locked.")

        item_mime = (mimeType.strip() if mimeType is not None else item.get("mime_type"))
        if not isinstance(item_mime, str) or not item_mime:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "mimeType is invalid.")

        # Compute next version number for item
        max_ver = 0
        for v in versions:
            if v.get("item_id") == fileId and isinstance(v.get("version_number"), int):
                if v["version_number"] > max_ver:
                    max_ver = v["version_number"]
        new_ver_num = max_ver + 1

        ver_row = {
            "id": _new_id("ver"),
            "item_id": fileId,
            "version_number": new_ver_num,
            "blob_id": blob_id,
            "mime_type": item_mime,
            "size_bytes": size_bytes,
            "md5_checksum": md5,
            "created_by_principal": item.get("modified_by_principal") or item.get("owner_principal") or "anonymous@local",
            "created_at": now,
            "updated_at": now,
            "status": "active",
            "change_sequence": next_seq
        }
        versions.append(ver_row)

        # Update item pointers
        item["content_blob_id"] = blob_id
        item["size_bytes"] = size_bytes
        item["mime_type"] = item_mime
        item["md5_checksum"] = md5
        item["modified_at"] = now
        item["updated_at"] = now
        item["modified_by_principal"] = item.get("modified_by_principal") or item.get("owner_principal") or "anonymous@local"
        if item_mime.startswith("text/") or item_mime == "application/json":
            item["content_text_encoding"] = item.get("content_text_encoding") or "utf-8"
        else:
            item["content_text_encoding"] = None

        _save("file_versions.json", versions)
        _save("drive_items.json", items)
        _log("ok")
        return {"item": item, "version": ver_row}

    # Create new file item + version 1
    item_mime = (mimeType.strip() if mimeType is not None else "application/octet-stream")
    if not isinstance(item_mime, str) or not item_mime:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "mimeType is invalid.")

    # Choose owner_principal from existing dataset, else anonymous
    owner = next((r.get("owner_principal") for r in items if r.get("owner_principal") and r.get("shared_drive_id") is None), None) or "anonymous@local"

    new_item_id = _new_id("it")
    item_row = {
        "id": new_item_id,
        "shared_drive_id": None,
        "owner_principal": owner,
        "name": f"Untitled" if size_bytes else "Untitled",
        "mime_type": item_mime,
        "item_type": "file",
        "shortcut_target_item_id": None,
        "description": None,
        "starred": False,
        "locked": False,
        "trashed_at": None,
        "status": "active",
        "size_bytes": size_bytes,
        "content_blob_id": blob_id,
        "content_text_encoding": "utf-8" if (item_mime.startswith("text/") or item_mime == "application/json") else None,
        "md5_checksum": md5,
        "modified_by_principal": owner,
        "modified_at": now,
        "created_at": now,
        "updated_at": now
    }
    items.append(item_row)

    ver_row = {
        "id": _new_id("ver"),
        "item_id": new_item_id,
        "version_number": 1,
        "blob_id": blob_id,
        "mime_type": item_mime,
        "size_bytes": size_bytes,
        "md5_checksum": md5,
        "created_by_principal": owner,
        "created_at": now,
        "updated_at": now,
        "status": "active",
        "change_sequence": next_seq
    }
    versions.append(ver_row)

    _save("drive_items.json", items)
    _save("file_versions.json", versions)
    _log("ok")
    return {"item": item_row, "version": ver_row}

def drive_append_text(fileId, text, **_extra):
    import json, os, datetime, time, base64, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _as_int(x):
        if isinstance(x, bool) or x is None:
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        if isinstance(x, str) and x.isdigit():
            try:
                return int(x)
            except Exception:
                return None
        return None

    def _get_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            return {"limits": {}, "quota": {}}
        limits = cfg.get("limits") or cfg.get("rate_limit") or {}
        quota = cfg.get("quota") or {}
        return {"limits": limits or {}, "quota": quota or {}}

    def _get_scope():
        items = _load("drive_items.json")
        if not isinstance(items, list):
            items = []
        owners = []
        for it in items:
            if isinstance(it, dict) and it.get("status") != "deleted":
                op = it.get("owner_principal")
                if isinstance(op, str) and op:
                    owners.append(op)
        if owners:
            owners.sort()
            return {"principal": owners[0]}
        sds = _load("shared_drives.json")
        if not isinstance(sds, list):
            sds = []
        creators = []
        for d in sds:
            if isinstance(d, dict) and d.get("status") == "active":
                cp = d.get("created_by_principal")
                if isinstance(cp, str) and cp:
                    creators.append(cp)
        if creators:
            creators.sort()
            return {"principal": creators[0]}
        return {"principal": None}

    def _has_write_access(principal, item, permissions_rows):
        if not isinstance(item, dict) or item.get("status") == "deleted":
            return False
        if principal and item.get("owner_principal") == principal:
            return True
        if item.get("shared_drive_id") is not None:
            # shared drive items considered writable by ambient principal if any
            return True
        iid = item.get("id")
        for p in permissions_rows:
            if not isinstance(p, dict):
                continue
            if p.get("status") != "active" or p.get("item_id") != iid:
                continue
            if p.get("role") in ("writer", "organizer"):
                t = p.get("type")
                if t == "anyone":
                    return True
                if t in ("user", "group"):
                    ea = p.get("email_address")
                    if principal and isinstance(ea, str) and ea and (ea == principal or ea == principal.replace("user:", "")):
                        return True
                if t == "domain":
                    email = (principal or "").replace("user:", "")
                    dom = p.get("domain")
                    if isinstance(dom, str) and dom and "@" in email and email.split("@", 1)[1].lower() == dom.lower():
                        return True
        return False

    def _enforce_and_log(status_code, credential_used=None):
        cfg = _get_limits()
        limits = cfg["limits"]
        quota = cfg["quota"]
        rpm = _as_int(limits.get("requests_per_minute") or limits.get("requestsPerMinute"))
        rpd = _as_int(quota.get("requests_per_day") or quota.get("requestsPerDay") or limits.get("requests_per_day") or limits.get("requestsPerDay"))

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

        if isinstance(rpm, int) and rpm > 0:
            cutoff = now_utc - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpm:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_append_text",
                        "status": "RATE_LIMIT",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("RATE_LIMIT", "Rate limit exceeded")

        if isinstance(rpd, int) and rpd > 0:
            cutoff = now_utc - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpd:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_append_text",
                        "status": "QUOTA_EXCEEDED",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        latency_ms = int((time.time() - t0) * 1000)
        logs.append(
            {
                "timestamp": _now_iso(),
                "endpoint": "drive_append_text",
                "status": status_code,
                "http_status": 200 if status_code == "OK" else 400,
                "latency_ms": latency_ms,
                "credential": credential_used,
            }
        )
        _save("request_logs.json", logs)
        return None

    # Validation (accept any non-empty string ids; audit used shared drive id by mistake and should return NOT_FOUND, not validation error)
    if not isinstance(fileId, str) or not fileId.strip():
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "fileId must be a non-empty string")
    if not isinstance(text, str):
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "text must be a string")

    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    perms = _load("permissions.json")
    if not isinstance(perms, list):
        perms = []
    versions = _load("file_versions.json")
    if not isinstance(versions, list):
        versions = []
    blobs = _load("blobs.json")
    if not isinstance(blobs, list):
        blobs = []

    item = None
    for it in items:
        if isinstance(it, dict) and it.get("id") == fileId and it.get("status") != "deleted":
            item = it
            break
    if item is None:
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "File not found.")

    if item.get("status") != "active":
        e = _enforce_and_log("INVALID_TRANSITION")
        if isinstance(e, dict):
            return e
        return _err("INVALID_TRANSITION", "FAILED_PRECONDITION: item is not active")

    if item.get("item_type") != "file":
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "FAILED_PRECONDITION: cannot append text to a non-file item")

    mt = item.get("mime_type") or ""
    # allow text/* and application/json (configurable but keep simple)
    if not (isinstance(mt, str) and (mt.startswith("text/") or mt == "application/json")):
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "FAILED_PRECONDITION: file is not a supported text type")

    scope = _get_scope()
    principal = scope.get("principal")

    # locked check
    if item.get("locked") is True and not _has_write_access(principal, item, perms):
        e = _enforce_and_log("UNAUTHORIZED")
        if isinstance(e, dict):
            return e
        return _err("UNAUTHORIZED", "File is locked; insufficient permission to modify")

    if not _has_write_access(principal, item, perms):
        e = _enforce_and_log("UNAUTHORIZED")
        if isinstance(e, dict):
            return e
        return _err("UNAUTHORIZED", "Not authorized to modify file")

    # Load current content if present (best-effort)
    existing = b""
    blob_id = item.get("content_blob_id")
    if isinstance(blob_id, str) and blob_id:
        br = None
        for b in blobs:
            if isinstance(b, dict) and b.get("id") == blob_id:
                br = b
                break
        if br is not None:
            data_b64 = br.get("data_base64") or br.get("data") or br.get("base64")
            if isinstance(data_b64, str) and data_b64:
                try:
                    existing = base64.b64decode(data_b64.encode("utf-8"), validate=False)
                except Exception:
                    existing = b""
            elif isinstance(br.get("text"), str):
                enc = item.get("content_text_encoding") or "utf-8"
                try:
                    existing = br.get("text").encode(enc, errors="replace")
                except Exception:
                    existing = br.get("text").encode("utf-8", errors="replace")

    enc = item.get("content_text_encoding") or "utf-8"
    try:
        append_bytes = text.encode(enc)
    except Exception:
        append_bytes = text.encode("utf-8", errors="replace")
        enc = "utf-8"

    new_content = existing + append_bytes
    new_blob_id = "gdrv_blob_" + secrets.token_hex(12)
    new_md5 = hashlib.md5(new_content).hexdigest() if new_content is not None else None  # noqa: S324

    blobs.append(
        {
            "id": new_blob_id,
            "data_base64": base64.b64encode(new_content).decode("ascii"),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
    )

    # New file version
    max_v = 0
    max_seq = 0
    for v in versions:
        if not isinstance(v, dict):
            continue
        if v.get("item_id") == fileId:
            vn = v.get("version_number")
            if isinstance(vn, int) and vn > max_v:
                max_v = vn
        cs = v.get("change_sequence")
        if isinstance(cs, int) and cs > max_seq:
            max_seq = cs

    new_version_number = max_v + 1
    new_seq = max_seq + 1 if max_seq > 0 else 1

    new_ver_id = "gdrv_ver_" + secrets.token_hex(12)
    versions.append(
        {
            "id": new_ver_id,
            "item_id": fileId,
            "version_number": new_version_number,
            "blob_id": new_blob_id,
            "mime_type": mt,
            "size_bytes": len(new_content),
            "md5_checksum": new_md5,
            "created_by_principal": principal or (item.get("owner_principal") or "user:unknown"),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
            "status": "active",
            "change_sequence": new_seq,
        }
    )

    # Update item pointers/metadata
    now = _now_iso()
    item["content_blob_id"] = new_blob_id
    item["size_bytes"] = len(new_content)
    item["md5_checksum"] = new_md5
    item["content_text_encoding"] = enc
    item["modified_by_principal"] = principal or item.get("modified_by_principal") or (item.get("owner_principal") or "user:unknown")
    item["modified_at"] = now
    item["updated_at"] = now

    _save("blobs.json", blobs)
    _save("file_versions.json", versions)
    _save("drive_items.json", items)

    e = _enforce_and_log("OK")
    if isinstance(e, dict):
        return e
    return {"item": dict(item), "newVersion": {"id": new_ver_id, "version_number": new_version_number, "change_sequence": new_seq}}

