        if cur == "deleted":
            # idempotent: already deleted
            e = _enforce_and_log("OK")
            if isinstance(e, dict):
                return e
            return {"item": dict(item)}
        if cur not in ("active", "trashed"):
            e = _enforce_and_log("INVALID_TRANSITION")
            if isinstance(e, dict):
                return e
            return _err("INVALID_TRANSITION", f"Cannot permanently delete from state '{cur}'")
        item["status"] = "deleted"
        item["updated_at"] = now
        item["modified_at"] = now
        item["modified_by_principal"] = principal or item.get("modified_by_principal") or (item.get("owner_principal") or "user:unknown")
        # Remove parent links and permission/comment/version rows to simulate FK cascades
        parents2 = [r for r in parents if not (isinstance(r, dict) and r.get("item_id") == fileId)]
        perms2 = [r for r in perms if not (isinstance(r, dict) and r.get("item_id") == fileId)]
        comments2 = [r for r in comments if not (isinstance(r, dict) and r.get("item_id") == fileId)]
        versions2 = [r for r in versions if not (isinstance(r, dict) and r.get("item_id") == fileId)]
        if len(parents2) == len(parents) and len(perms2) == len(perms) and len(comments2) == len(comments) and len(versions2) == len(versions) and cur == item.get("status"):
            # item updated anyway; effect exists
            pass
        parents, perms, comments, versions = parents2, perms2, comments2, versions2
        _save("drive_item_parents.json", parents)
        _save("permissions.json", perms)
        _save("comments.json", comments)
        _save("file_versions.json", versions)
        _save("drive_items.json", items)
        e = _enforce_and_log("OK")
        if isinstance(e, dict):
            return e
        return {"item": dict(item)}

    # trash by default
    if cur == "trashed":
        # idempotent
        e = _enforce_and_log("OK")
        if isinstance(e, dict):
            return e
        return {"item": dict(item)}
    if cur != "active":
        e = _enforce_and_log("INVALID_TRANSITION")
        if isinstance(e, dict):
            return e
        return _err("INVALID_TRANSITION", f"Cannot trash from state '{cur}'")

    item["status"] = "trashed"
    item["trashed_at"] = now
    item["updated_at"] = now
    item["modified_at"] = now
    item["modified_by_principal"] = principal or item.get("modified_by_principal") or (item.get("owner_principal") or "user:unknown")
    _save("drive_items.json", items)

    e = _enforce_and_log("OK")
    if isinstance(e, dict):
        return e
    return {"item": dict(item)}

def drive_share(fileId, role, type, emailAddress=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "drive_share"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(fileId, str) or not fileId.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "fileId must be a non-empty string")
        if not isinstance(role, str) or role not in ("reader", "commenter", "writer"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "role must be one of: reader, commenter, writer")
        if not isinstance(type, str) or type not in ("user", "group", "domain", "anyone"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "type must be one of: user, group, domain, anyone")
        if emailAddress is not None and not isinstance(emailAddress, str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "emailAddress must be a string when provided")

        # validate emailAddress usage per rules
        if type in ("user", "group"):
            if not emailAddress or not emailAddress.strip():
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "emailAddress is required for type user/group")
        else:
            if emailAddress is not None:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "emailAddress must be null for type domain/anyone")

        items = _load("drive_items.json")
        if not isinstance(items, list):
            items = []
        item = None
        for r in items:
            if isinstance(r, dict) and r.get("id") == fileId:
                item = r
                break
        if not item or item.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Item not found")

        # cannot grant organizer unless in shared drive (not applicable here since organizer not in enum)
        perms = _load("permissions.json")
        if not isinstance(perms, list):
            perms = []

        # Ambient auth: pick a reasonable principal (prefer item owner, else creator of shared drive, else any)
        principal = item.get("modified_by_principal") or item.get("owner_principal") or "principal_unknown"

        now = _now()

        # upsert active unique(item_id, type, coalesce(email_address,''), coalesce(domain,''))
        key_email = (emailAddress or "").strip() if type in ("user", "group") else ""
        key_domain = ""  # drive_share tool doesn't accept domain param
        found_idx = None
        found = None
        for i, p in enumerate(perms):
            if not isinstance(p, dict):
                continue
            if p.get("item_id") != fileId or p.get("status") != "active":
                continue
            if p.get("type") != type:
                continue
            if (p.get("email_address") or "") == key_email and (p.get("domain") or "") == key_domain:
                found_idx = i
                found = p
                break

        if found:
            # update role
            found["role"] = role
            found["updated_at"] = now
            perms[found_idx] = found
            _save("permissions.json", perms)
            _log("success", None)
            return {"permission": found}

        # create new permission id
        next_num = 1
        for p in perms:
            if isinstance(p, dict):
                pid = p.get("id", "")
                if isinstance(pid, str) and pid.startswith("gdrv_perm_"):
                    tail = pid.split("_")[-1]
                    if tail.isdigit():
                        next_num = max(next_num, int(tail) + 1)
        perm_id = f"gdrv_perm_{next_num}"

        newp = {
            "id": perm_id,
            "item_id": fileId,
            "type": type,
            "role": role,
            "email_address": key_email if type in ("user", "group") else None,
            "domain": None,
            "allow_discovery": False,
            "status": "active",
            "created_by_principal": principal,
            "created_at": now,
            "updated_at": now,
        }

        # enforce uniqueness (defensive): if another active row matches, conflict
        for p in perms:
            if not isinstance(p, dict) or p.get("status") != "active":
                continue
            if p.get("item_id") == fileId and p.get("type") == type and (p.get("email_address") or "") == (newp.get("email_address") or "") and (p.get("domain") or "") == "":
                _log("error", "CONFLICT")
                return _err("CONFLICT", "An active permission for this target already exists")

        perms.append(newp)
        _save("permissions.json", perms)
        _log("success", None)
        return {"permission": newp}
    except Exception as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def drive_comment(fileId, content, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _as_int(x):
        if isinstance(x, bool) or x is None:
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        if isinstance(x, str) and x.isdigit():
            try:
                return int(x)
            except Exception:
                return None
        return None

    def _get_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            return {"limits": {}, "quota": {}}
        limits = cfg.get("limits") or cfg.get("rate_limit") or {}
        quota = cfg.get("quota") or {}
        return {"limits": limits or {}, "quota": quota or {}}

    def _get_scope():
        items = _load("drive_items.json")
        if not isinstance(items, list):
            items = []
        owners = []
        for it in items:
            if isinstance(it, dict) and it.get("status") != "deleted":
                op = it.get("owner_principal")
                if isinstance(op, str) and op:
                    owners.append(op)
        if owners:
            owners.sort()
            return {"principal": owners[0]}
        sds = _load("shared_drives.json")
        if not isinstance(sds, list):
            sds = []
        creators = []
        for d in sds:
            if isinstance(d, dict) and d.get("status") == "active":
                cp = d.get("created_by_principal")
                if isinstance(cp, str) and cp:
                    creators.append(cp)
        if creators:
            creators.sort()
            return {"principal": creators[0]}
        return {"principal": None}

    def _has_comment_access(principal, item, permissions_rows):
        if not isinstance(item, dict) or item.get("status") == "deleted":
            return False
        if principal and item.get("owner_principal") == principal:
            return True
        if item.get("shared_drive_id") is not None:
            return True
        iid = item.get("id")
        for p in permissions_rows:
            if not isinstance(p, dict):
                continue
            if p.get("status") != "active" or p.get("item_id") != iid:
                continue
            # reader/commenter/writer/organizer can comment (simplified)
            if p.get("role") in ("commenter", "writer", "organizer"):
                return True
            if p.get("type") == "anyone" and p.get("role") in ("commenter", "writer", "organizer"):
                return True
        return False

    def _enforce_and_log(status_code, credential_used=None):
        cfg = _get_limits()
        limits = cfg["limits"]
        quota = cfg["quota"]
        rpm = _as_int(limits.get("requests_per_minute") or limits.get("requestsPerMinute"))
        rpd = _as_int(quota.get("requests_per_day") or quota.get("requestsPerDay") or limits.get("requests_per_day") or limits.get("requestsPerDay"))

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

        if isinstance(rpm, int) and rpm > 0:
            cutoff = now_utc - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpm:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_comment",
                        "status": "RATE_LIMIT",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("RATE_LIMIT", "Rate limit exceeded")

        if isinstance(rpd, int) and rpd > 0:
            cutoff = now_utc - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpd:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_comment",
                        "status": "QUOTA_EXCEEDED",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        latency_ms = int((time.time() - t0) * 1000)
        logs.append(
            {
                "timestamp": _now_iso(),
                "endpoint": "drive_comment",
                "status": status_code,
                "http_status": 200 if status_code == "OK" else 400,
                "latency_ms": latency_ms,
                "credential": credential_used,
            }
        )
        _save("request_logs.json", logs)
        return None

    if not isinstance(fileId, str) or not fileId.strip():
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "fileId must be a non-empty string")
    if not isinstance(content, str) or not content.strip():
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "content must be a non-empty string")

    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    perms = _load("permissions.json")
    if not isinstance(perms, list):
        perms = []
    comments = _load("comments.json")
    if not isinstance(comments, list):
        comments = []

    item = None
    for it in items:
        if isinstance(it, dict) and it.get("id") == fileId and it.get("status") != "deleted":
            item = it
            break
    if item is None:
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "File not found")

    if item.get("item_type") != "file":
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "FAILED_PRECONDITION: comments allowed only on files")

    if item.get("status") != "active":
        e = _enforce_and_log("INVALID_TRANSITION")
        if isinstance(e, dict):
            return e
        return _err("INVALID_TRANSITION", "FAILED_PRECONDITION: cannot comment on non-active item")

    scope = _get_scope()
    principal = scope.get("principal") or (item.get("owner_principal") or "user:unknown")

    if not _has_comment_access(principal, item, perms):
        e = _enforce_and_log("UNAUTHORIZED")
        if isinstance(e, dict):
            return e
        return _err("UNAUTHORIZED", "Not authorized to comment on this file")

    now = _now_iso()
    cmt_id = "gdrv_cmt_" + secrets.token_hex(12)
    row = {
        "id": cmt_id,
        "item_id": fileId,
        "parent_comment_id": None,
        "author_principal": principal,
        "content": content,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    comments.append(row)
    _save("comments.json", comments)

    e = _enforce_and_log("OK")
    if isinstance(e, dict):
        return e
    return {"comment": dict(row)}

