    scope = _get_scope()
    principal = scope.get("principal")

    if not _has_access(principal, src, perms, want_write=False):
        e = _enforce_and_log("UNAUTHORIZED")
        if isinstance(e, dict):
            return e
        return _err("UNAUTHORIZED", "Not authorized to read source item")

    if not _has_access(principal, dest, perms, want_write=True):
        # creating in folder requires write on folder
        e = _enforce_and_log("UNAUTHORIZED")
        if isinstance(e, dict):
            return e
        return _err("UNAUTHORIZED", "Not authorized to create items in destination folder")

    now = _now_iso()
    new_id = "gdrv_itm_" + secrets.token_hex(12)
    name = (newName.strip() if isinstance(newName, str) and newName.strip() else src.get("name"))
    if not isinstance(name, str) or not name.strip():
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "Resulting name must be non-empty")

    new_item = {
        "id": new_id,
        "shared_drive_id": src.get("shared_drive_id"),
        "owner_principal": src.get("owner_principal") or (principal or "user:unknown"),
        "name": name,
        "mime_type": src.get("mime_type"),
        "item_type": src.get("item_type"),
        "shortcut_target_item_id": src.get("shortcut_target_item_id"),
        "description": src.get("description"),
        "starred": bool(src.get("starred")),
        "locked": False,  # copy starts unlocked (simplified)
        "trashed_at": None,
        "status": "active",
        "size_bytes": int(src.get("size_bytes") or 0),
        "content_blob_id": src.get("content_blob_id"),
        "content_text_encoding": src.get("content_text_encoding"),
        "md5_checksum": src.get("md5_checksum"),
        "modified_by_principal": principal or (src.get("modified_by_principal") or "user:unknown"),
        "modified_at": now,
        "created_at": now,
        "updated_at": now,
    }

    items.append(new_item)
    parents.append(
        {
            "id": "gdrv_par_" + secrets.token_hex(12),
            "item_id": new_id,
            "parent_folder_id": parentFolderId,
            "created_at": now,
            "updated_at": now,
        }
    )

    # If file: create a new version referencing same blob (copy-on-write)
    if new_item.get("item_type") == "file" and isinstance(new_item.get("content_blob_id"), str) and new_item.get("content_blob_id"):
        max_seq = 0
        for v in versions:
            if isinstance(v, dict):
                cs = v.get("change_sequence")
                if isinstance(cs, int) and cs > max_seq:
                    max_seq = cs
        new_seq = max_seq + 1 if max_seq > 0 else 1
        versions.append(
            {
                "id": "gdrv_ver_" + secrets.token_hex(12),
                "item_id": new_id,
                "version_number": 1,
                "blob_id": new_item.get("content_blob_id"),
                "mime_type": new_item.get("mime_type"),
                "size_bytes": new_item.get("size_bytes"),
                "md5_checksum": new_item.get("md5_checksum"),
                "created_by_principal": principal or (new_item.get("owner_principal") or "user:unknown"),
                "created_at": now,
                "updated_at": now,
                "status": "active",
                "change_sequence": new_seq,
            }
        )

    _save("drive_items.json", items)
    _save("drive_item_parents.json", parents)
    _save("file_versions.json", versions)

    e = _enforce_and_log("OK")
    if isinstance(e, dict):
        return e
    return {"item": dict(new_item)}

