    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "drive_rename"
    status = "error"
    used_credential = None

    def _log(status_code):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": endpoint,
            "credential_id": used_credential,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z"
        })
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rate = cfg.get("rate_limit_per_minute", 120)
        quota = cfg.get("quota_per_day", 5000)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        per_min = 0
        per_day = 0
        for r in logs:
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1

        if isinstance(rate, int) and rate >= 0 and per_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(quota, int) and quota >= 0 and per_day >= quota:
            return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    try:
        lim = _check_limits()
        if lim:
            _log(lim["error"]["code"])
            return lim

        if not isinstance(itemId, str) or not re.match(r"^gdrv_itm_[0-9A-HJKMNP-TV-Z]{18,}$", itemId):
            e = _err("VALIDATION_ERROR", "Invalid itemId")
            _log(e["error"]["code"])
            return e
        if not isinstance(name, str) or name.strip() == "":
            e = _err("VALIDATION_ERROR", "Invalid name")
            _log(e["error"]["code"])
            return e
        name = name.strip()

        items = _load("drive_items.json")
        if not isinstance(items, list):
            items = []

        item = next((x for x in items if x.get("id") == itemId), None)
        if not item or item.get("status") == "deleted":
            e = _err("NOT_FOUND", "Item not found")
            _log(e["error"]["code"])
            return e

        # Ambient auth: choose a principal that can act. Prefer owner; else any active writer/organizer permission.
        perms = _load("permissions.json")
        if not isinstance(perms, list):
            perms = []
        principal = None
        if isinstance(item.get("owner_principal"), str) and item["owner_principal"]:
            principal = item["owner_principal"]
        else:
            for p in perms:
                if p.get("item_id") == itemId and p.get("status") == "active" and p.get("role") in ("writer", "organizer"):
                    if p.get("type") in ("user", "group") and isinstance(p.get("email_address"), str) and p["email_address"]:
                        principal = p["email_address"]
                        break
        if not principal:
            e = _err("UNAUTHORIZED", "No authenticated principal can modify this item")
            _log(e["error"]["code"])
            return e

        # Locked item restriction: rename is a metadata mutation; require writer/organizer if locked
        if item.get("locked") is True and principal != item.get("owner_principal"):
            ok = False
            for p in perms:
                if p.get("item_id") == itemId and p.get("status") == "active" and p.get("role") in ("writer", "organizer"):
                    if (p.get("type") in ("user", "group") and p.get("email_address") == principal) or \
                       (p.get("type") == "domain" and isinstance(principal, str) and principal.endswith("@" + str(p.get("domain")))):
                        ok = True
                        break
                    if p.get("type") == "anyone":
                        ok = True
                        break
            if not ok:
                e = _err("CONFLICT", "Item is locked and cannot be renamed with current permissions")
                _log(e["error"]["code"])
                return e

        # No success without effect: if same name, treat as conflict (rename didn't happen)
        if item.get("name") == name:
            e = _err("CONFLICT", "Item already has the specified name")
            _log(e["error"]["code"])
            return e

        now = datetime.datetime.utcnow().isoformat() + "Z"
        item["name"] = name
        item["modified_by_principal"] = principal
        item["modified_at"] = now
        item["updated_at"] = now

        _save("drive_items.json", items)

        status = "ok"
        resp = {"item": item}
        _log("ok")
        return resp
    except Exception:
        e = _err("CONFLICT", "Unexpected server error")
        _log(e["error"]["code"])
        return e

