            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z"
        })
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rate = cfg.get("rate_limit_per_minute", 120)
        quota = cfg.get("quota_per_day", 5000)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        per_min = 0
        per_day = 0
        for r in logs:
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1

        if isinstance(rate, int) and rate >= 0 and per_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(quota, int) and quota >= 0 and per_day >= quota:
            return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    def _is_folder(items_by_id, fid):
        it = items_by_id.get(fid)
        return bool(it and it.get("status") != "deleted" and it.get("item_type") == "folder")

    def _pick_nearest_valid_parent(item_id, parents, items_by_id):
        # Google-like behavior: restore to any remaining valid parent; if none, keep no parents (implementation).
        rels = [r for r in parents if r.get("item_id") == item_id]
        for r in rels:
            pf = r.get("parent_folder_id")
            if _is_folder(items_by_id, pf):
                # also require same drive scope
                child = items_by_id.get(item_id)
                par = items_by_id.get(pf)
                if child and par and child.get("shared_drive_id") == par.get("shared_drive_id"):
                    return pf
        return None

    try:
        lim = _check_limits()
        if lim:
            _log(lim["error"]["code"])
            return lim

        if not isinstance(itemId, str) or not re.match(r"^gdrv_itm_[0-9A-HJKMNP-TV-Z]{18,}$", itemId):
            e = _err("VALIDATION_ERROR", "Invalid itemId")
            _log(e["error"]["code"])
            return e

        items = _load("drive_items.json")
        if not isinstance(items, list):
            items = []
        items_by_id = {x.get("id"): x for x in items if isinstance(x, dict) and isinstance(x.get("id"), str)}

        item = items_by_id.get(itemId)
        if not item or item.get("status") == "deleted":
            e = _err("NOT_FOUND", "Item not found")
            _log(e["error"]["code"])
            return e

        if item.get("status") != "trashed":
            e = _err("CONFLICT", "Item is not trashed")
            _log(e["error"]["code"])
            return e

        perms = _load("permissions.json")
        if not isinstance(perms, list):
            perms = []
        principal = None
        if isinstance(item.get("owner_principal"), str) and item["owner_principal"]:
            principal = item["owner_principal"]
        else:
            for p in perms:
                if p.get("item_id") == itemId and p.get("status") == "active" and p.get("role") in ("writer", "organizer"):
                    if p.get("type") in ("user", "group") and isinstance(p.get("email_address"), str) and p["email_address"]:
                        principal = p["email_address"]
                        break
        if not principal:
            e = _err("UNAUTHORIZED", "No authenticated principal can restore this item")
            _log(e["error"]["code"])
            return e

        parents = _load("drive_item_parents.json")
        if not isinstance(parents, list):
            parents = []

        # Validate there exists at least one valid parent folder; else restore with no parents (nearest valid parent missing)
        nearest_parent = _pick_nearest_valid_parent(itemId, parents, items_by_id)
        if nearest_parent is None:
            # Keep existing relations but if they point to invalid folders, remove them so the restored item is reachable nowhere.
            # This is consistent and observable.
            new_parents = []
            changed = False
            for r in parents:
                if r.get("item_id") != itemId:
                    new_parents.append(r)
                    continue
                pf = r.get("parent_folder_id")
                if _is_folder(items_by_id, pf) and items_by_id[itemId].get("shared_drive_id") == items_by_id[pf].get("shared_drive_id"):
                    new_parents.append(r)
                else:
                    changed = True
            if changed:
                _save("drive_item_parents.json", new_parents)
                parents = new_parents

        now = datetime.datetime.utcnow().isoformat() + "Z"
        # lifecycle transition trashed -> active
        item["status"] = "active"
        item["trashed_at"] = None
        item["modified_by_principal"] = principal
        item["modified_at"] = now
        item["updated_at"] = now

        _save("drive_items.json", items)
        _log("ok")
        return {"item": item}
    except Exception:
        e = _err("CONFLICT", "Unexpected server error")
        _log(e["error"]["code"])
        return e

