        if pageSize is None:
            pageSize = 50
        if isinstance(pageSize, bool) or not (isinstance(pageSize, int) or isinstance(pageSize, float)):
            e = _err("VALIDATION_ERROR", "Invalid pageSize")
            _log(e["error"]["code"])
            return e
        pageSize = int(pageSize)
        if pageSize <= 0 or pageSize > 200:
            e = _err("VALIDATION_ERROR", "pageSize out of range")
            _log(e["error"]["code"])
            return e

        offset = _decode_cursor(pageToken)
        if offset is None:
            e = _err("VALIDATION_ERROR", "Invalid pageToken")
            _log(e["error"]["code"])
            return e

        items = _load("drive_items.json")
        if not isinstance(items, list):
            items = []
        item = next((x for x in items if x.get("id") == fileId), None)
        if not item or item.get("status") == "deleted":
            e = _err("NOT_FOUND", "File not found")
            _log(e["error"]["code"])
            return e
        if item.get("item_type") != "file":
            e = _err("VALIDATION_ERROR", "Item is not a file")
            _log(e["error"]["code"])
            return e

        # Ambient auth: require that some principal can view it (owner or any active permission)
        perms = _load("permissions.json")
        if not isinstance(perms, list):
            perms = []
        principal = None
        if isinstance(item.get("owner_principal"), str) and item["owner_principal"]:
            principal = item["owner_principal"]
        else:
            for p in perms:
                if p.get("item_id") == fileId and p.get("status") == "active":
                    if p.get("type") in ("user", "group") and isinstance(p.get("email_address"), str) and p["email_address"]:
                        principal = p["email_address"]
                        break
                    if p.get("type") in ("domain", "anyone"):
                        principal = "anonymous"
                        break
        if not principal:
            e = _err("UNAUTHORIZED", "No authenticated principal can view this file")
            _log(e["error"]["code"])
            return e

        versions = _load("file_versions.json")
        if not isinstance(versions, list):
            versions = []

        rows = [v for v in versions if v.get("item_id") == fileId and v.get("status") == "active"]
        rows.sort(key=lambda r: (r.get("version_number") if isinstance(r.get("version_number"), int) else -1), reverse=True)

        total = len(rows)
        page = rows[offset: offset + pageSize]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_token = _encode_cursor(next_offset) if has_more else None

        _log("ok")
        return {
            "versions": page,
            "total": total,
            "pageSize": pageSize,
            "pageToken": pageToken,
            "nextPageToken": next_token,
            "hasMore": has_more
        }
    except Exception:
        e = _err("CONFLICT", "Unexpected server error")
        _log(e["error"]["code"])
        return e

def drive_file_lock(fileId, locked, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _as_int(x):
        if isinstance(x, bool) or x is None:
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        if isinstance(x, str) and x.isdigit():
            try:
                return int(x)
            except Exception:
                return None
        return None

    def _get_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            return {"limits": {}, "quota": {}}
        limits = cfg.get("limits") or cfg.get("rate_limit") or {}
        quota = cfg.get("quota") or {}
        return {"limits": limits or {}, "quota": quota or {}}

    def _get_scope():
        items = _load("drive_items.json")
        if not isinstance(items, list):
            items = []
        owners = []
        for it in items:
            if isinstance(it, dict) and it.get("status") != "deleted":
                op = it.get("owner_principal")
                if isinstance(op, str) and op:
                    owners.append(op)
        if owners:
            owners.sort()
            return {"principal": owners[0]}
        return {"principal": None}

    def _has_write_access(principal, item, permissions_rows):
        if not isinstance(item, dict) or item.get("status") == "deleted":
            return False
        if principal and item.get("owner_principal") == principal:
            return True
        if item.get("shared_drive_id") is not None:
            return True
        iid = item.get("id")
        for p in permissions_rows:
            if not isinstance(p, dict):
                continue
            if p.get("status") != "active" or p.get("item_id") != iid:
                continue
            if p.get("role") in ("writer", "organizer"):
                return True
        return False

    def _enforce_and_log(status_code, credential_used=None):
        cfg = _get_limits()
        limits = cfg["limits"]
        quota = cfg["quota"]
        rpm = _as_int(limits.get("requests_per_minute") or limits.get("requestsPerMinute"))
        rpd = _as_int(quota.get("requests_per_day") or quota.get("requestsPerDay") or limits.get("requests_per_day") or limits.get("requestsPerDay"))

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

        if isinstance(rpm, int) and rpm > 0:
            cutoff = now_utc - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpm:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_file_lock",
                        "status": "RATE_LIMIT",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("RATE_LIMIT", "Rate limit exceeded")

        if isinstance(rpd, int) and rpd > 0:
            cutoff = now_utc - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpd:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_file_lock",
                        "status": "QUOTA_EXCEEDED",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        latency_ms = int((time.time() - t0) * 1000)
        logs.append(
            {
                "timestamp": _now_iso(),
                "endpoint": "drive_file_lock",
                "status": status_code,
                "http_status": 200 if status_code == "OK" else 400,
                "latency_ms": latency_ms,
                "credential": credential_used,
            }
        )
        _save("request_logs.json", logs)
        return None

    if not isinstance(fileId, str) or not fileId.strip():
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "fileId must be a non-empty string")
    if not isinstance(locked, bool):
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "locked must be a boolean")

    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    perms = _load("permissions.json")
    if not isinstance(perms, list):
        perms = []

    item = None
    for it in items:
        if isinstance(it, dict) and it.get("id") == fileId and it.get("status") != "deleted":
            item = it
            break
    if item is None:
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "File not found")

    if item.get("item_type") != "file":
        e = _enforce_and_log("CONFLICT")
        if isinstance(e, dict):
            return e
        return _err("CONFLICT", "Item is not a lockable file")

    principal = _get_scope().get("principal")
    if not _has_write_access(principal, item, perms):
        e = _enforce_and_log("UNAUTHORIZED")
        if isinstance(e, dict):
            return e
        return _err("UNAUTHORIZED", "Not authorized to change lock state")

    # idempotent
    if bool(item.get("locked")) == locked:
        e = _enforce_and_log("OK")
        if isinstance(e, dict):
            return e
        return {"item": dict(item)}

    now = _now_iso()
    item["locked"] = locked
    item["updated_at"] = now
    item["modified_at"] = now
    item["modified_by_principal"] = principal or item.get("modified_by_principal") or (item.get("owner_principal") or "user:unknown")
    _save("drive_items.json", items)

    e = _enforce_and_log("OK")
    if isinstance(e, dict):
        return e
    return {"item": dict(item)}

def drive_permissions_list(fileId, pageToken=None, pageSize=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "drive_permissions_list"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, code=None, message=None):
        logs = _load("request_log.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if code:
            row["error_code"] = code
        if message:
            row["error_message"] = message
        logs.append(row)
        _save("request_log.json", logs)

    def _encode_cursor(i):
        raw = json.dumps({"i": i}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(tok):
        if tok is None:
            return 0
        if not isinstance(tok, str) or not tok:
            raise ValueError("bad token")
        pad = "=" * ((4 - (len(tok) % 4)) % 4)
        raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
        obj = json.loads(raw.decode("utf-8"))
        i = obj.get("i")
        if not isinstance(i, int) or i < 0:
            raise ValueError("bad token")
        return i

    try:
        if not isinstance(fileId, str) or not re.match(r"^gdrv_itm_[0-9A-HJKMNP-TV-Z]{20,}$", fileId):
            e = _err("VALIDATION_ERROR", "Invalid fileId.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if pageSize is None:
            limit = 100
        else:
            if not isinstance(pageSize, (int, float)) or isinstance(pageSize, bool):
                e = _err("VALIDATION_ERROR", "Invalid pageSize.")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e
            limit = int(pageSize)
            if limit <= 0 or limit > 1000:
                e = _err("VALIDATION_ERROR", "pageSize out of range (1..1000).")
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

        items = _load("drive_items.json")
        perms = _load("permissions.json")

        item = next((r for r in items if r.get("id") == fileId), None)
        if not item or item.get("status") == "deleted":
            e = _err("NOT_FOUND", "Item not found.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

        active = [p for p in perms if p.get("item_id") == fileId and p.get("status") == "active"]
        active.sort(key=lambda p: (p.get("created_at") or "", p.get("id") or ""))

        try:
            start = _decode_cursor(pageToken)
        except ValueError:
            e = _err("VALIDATION_ERROR", "Invalid pageToken.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

        total = len(active)
        page = active[start:start + limit]
        next_index = start + len(page)
        has_more = next_index < total
        out = {
            "permissions": page,
            "pageSize": limit,
            "total": total,
            "nextPageToken": _encode_cursor(next_index) if has_more else None,
        }
        _log("ok")
        return out
    except Exception as ex:
        e = _err("CONFLICT", "Operation failed.", detail=str(ex))
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

def drive_permission_update(fileId, permissionId, role, **_extra):
    import json, os, datetime, re, time

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, message=None, extra=None):
        # Best-effort request log; schema not provided, so discover common filenames.
        try:
            for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"):
                path = os.path.join(_DB, fname)
                if os.path.exists(path):
                    rows = _load(fname)
                    if not isinstance(rows, list):
                        rows = []
                    row = {
                        "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                        "endpoint": endpoint,
                        "status": status,
                        "message": message,
                        "timestamp": _now(),
                        "latency_ms": int((time.time() - _t0) * 1000),
                    }
                    if extra:
                        row.update(extra)
                    rows.append(row)
                    _save(fname, rows)
                    break
        except Exception:
            pass

    endpoint = "drive_permission_update"

    # Validate inputs
    if not isinstance(fileId, str) or not re.match(r"^gdrv_itm_[0-9A-HJKMNP-TV-Z]{20,}$", fileId):
        _log(endpoint, "VALIDATION_ERROR", "Invalid fileId")
        return _err("VALIDATION_ERROR", "fileId is malformed.")
    if not isinstance(permissionId, str) or not re.match(r"^gdrv_perm_[0-9A-HJKMNP-TV-Z]{20,}$", permissionId):
        _log(endpoint, "VALIDATION_ERROR", "Invalid permissionId")
        return _err("VALIDATION_ERROR", "permissionId is malformed.")
    if role not in ("reader", "commenter", "writer", "organizer"):
        _log(endpoint, "VALIDATION_ERROR", "Invalid role")
        return _err("VALIDATION_ERROR", "role must be one of reader/commenter/writer/organizer.")

    try:
        items = _load("drive_items.json")
        perms = _load("permissions.json")

        item = next((r for r in items if r.get("id") == fileId and r.get("status") != "deleted"), None)
        if not item:
            _log(endpoint, "NOT_FOUND", "File not found")
            return _err("NOT_FOUND", "File not found.")

        perm_idx = None
        perm = None
        for i, p in enumerate(perms):
            if p.get("id") == permissionId:
                perm_idx = i
                perm = p
                break
        if not perm or perm.get("item_id") != fileId:
            _log(endpoint, "NOT_FOUND", "Permission not found on file")
            return _err("NOT_FOUND", "Permission not found on this file.")

        if perm.get("status") != "active":
            _log(endpoint, "INVALID_TRANSITION", "Cannot update non-active permission")
            return _err("INVALID_TRANSITION", "Cannot update a revoked permission.")

        # Enforce organizer restriction
        if role == "organizer" and not item.get("shared_drive_id"):
            _log(endpoint, "VALIDATION_ERROR", "Organizer not allowed for My Drive")
            return _err("VALIDATION_ERROR", "Cannot grant organizer unless the item is in a shared drive.")

        # Update permission role
        now = _now()
        perm = dict(perm)
        perm["role"] = role
        perm["updated_at"] = now
        perms[perm_idx] = perm
        _save("permissions.json", perms)

        _log(endpoint, "OK", extra={"fileId": fileId, "permissionId": permissionId})
        return {"permission": perm}
    except Exception:
        _log(endpoint, "ERROR", "Unexpected error")
        return _err("CONFLICT", "Request could not be completed due to an internal conflict.")

