    if not isinstance(domain, str) or not domain.strip():
        _log(endpoint, "VALIDATION_ERROR", "Invalid domain")
        return _err("VALIDATION_ERROR", "domain is required.")
    domain = domain.strip().lower()
    # Basic domain validation (not exhaustive)
    if not re.match(r"^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$", domain):
        _log(endpoint, "VALIDATION_ERROR", "Malformed domain")
        return _err("VALIDATION_ERROR", "domain is invalid.")
    if allowDiscovery is not None and not isinstance(allowDiscovery, bool):
        _log(endpoint, "VALIDATION_ERROR", "Invalid allowDiscovery")
        return _err("VALIDATION_ERROR", "allowDiscovery must be a boolean when provided.")

    try:
        items = _load("drive_items.json")
        perms = _load("permissions.json")

        item = next((r for r in items if r.get("id") == fileId and r.get("status") != "deleted"), None)
        if not item:
            _log(endpoint, "NOT_FOUND", "File not found")
            return _err("NOT_FOUND", "File not found.")

        if role == "organizer" and not item.get("shared_drive_id"):
            _log(endpoint, "VALIDATION_ERROR", "Organizer not allowed for My Drive")
            return _err("VALIDATION_ERROR", "Cannot grant organizer unless the item is in a shared drive.")

        # Upsert by unique key: (item_id, type, email_address, domain) where status='active'
        existing_idx = None
        for i, p in enumerate(perms):
            if (
                p.get("item_id") == fileId
                and p.get("status") == "active"
                and p.get("type") == "domain"
                and (p.get("domain") or "").lower() == domain
                and (p.get("email_address") is None)
            ):
                existing_idx = i
                break

        now = _now()
        if existing_idx is not None:
            # Update role/allow_discovery
            p = dict(perms[existing_idx])
            p["role"] = role
            if allowDiscovery is not None:
                p["allow_discovery"] = allowDiscovery
            p["updated_at"] = now
            perms[existing_idx] = p
            _save("permissions.json", perms)
            _log(endpoint, "OK", extra={"fileId": fileId, "permissionId": p.get("id"), "upsert": True})
            return {"permission": p}

        # Create new permission
        perm_id = _gen_id("gdrv_perm")
        # created_by_principal is ambient; fall back to item modifier/owner
        created_by = item.get("modified_by_principal") or item.get("owner_principal") or "unknown"
        p = {
            "id": perm_id,
            "item_id": fileId,
            "type": "domain",
            "role": role,
            "email_address": None,
            "domain": domain,
            "allow_discovery": bool(allowDiscovery) if allowDiscovery is not None else False,
            "status": "active",
            "created_by_principal": created_by,
            "created_at": now,
            "updated_at": now,
        }
        perms.append(p)
        _save("permissions.json", perms)

        _log(endpoint, "OK", extra={"fileId": fileId, "permissionId": perm_id, "upsert": False})
        return {"permission": p}
    except Exception:
        _log(endpoint, "ERROR", "Unexpected error")
        return _err("CONFLICT", "Request could not be completed due to an internal conflict.")

def drive_permission_add_anyone(fileId, role, allowDiscovery=None, **_extra):
