    def _gen_id(prefix):
        import random
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(24))

    def _log(endpoint, status, message=None, extra=None):
        try:
            for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"):
