                    row = {
                        "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                        "endpoint": endpoint,
                        "status": status,
                        "message": message,
                        "timestamp": _now(),
                        "latency_ms": int((time.time() - _t0) * 1000),
                    }
                    if extra:
                        row.update(extra)
                    rows.append(row)
                    _save(fname, rows)
                    break
        except Exception:
            pass

    endpoint = "drive_permission_add_anyone"

    if not isinstance(fileId, str) or not re.match(r"^gdrv_itm_[0-9A-HJKMNP-TV-Z]{20,}$", fileId):
        _log(endpoint, "VALIDATION_ERROR", "Invalid fileId")
