        perms = _load("permissions.json")

        item = next((r for r in items if r.get("id") == fileId and r.get("status") != "deleted"), None)
        if not item:
            _log(endpoint, "NOT_FOUND", "File not found")
            return _err("NOT_FOUND", "File not found.")

        if role == "organizer" and not item.get("shared_drive_id"):
            _log(endpoint, "VALIDATION_ERROR", "Organizer not allowed for My Drive")
            return _err("VALIDATION_ERROR", "Cannot grant organizer unless the item is in a shared drive.")

        # Upsert unique key for anyone: (item_id, type='anyone', email_address null, domain null) where status='active'
        existing_idx = None
        for i, p in enumerate(perms):
            if (
                p.get("item_id") == fileId
                and p.get("status") == "active"
                and p.get("type") == "anyone"
                and p.get("email_address") is None
                and p.get("domain") is None
            ):
                existing_idx = i
                break

        now = _now()
        if existing_idx is not None:
            p = dict(perms[existing_idx])
            p["role"] = role
            if allowDiscovery is not None:
                p["allow_discovery"] = allowDiscovery
            p["updated_at"] = now
            perms[existing_idx] = p
            _save("permissions.json", perms)
            _log(endpoint, "OK", extra={"fileId": fileId, "permissionId": p.get("id"), "upsert": True})
            return {"permission": p}

        perm_id = _gen_id("gdrv_perm")
        created_by = item.get("modified_by_principal") or item.get("owner_principal") or "unknown"
        p = {
            "id": perm_id,
            "item_id": fileId,
            "type": "anyone",
            "role": role,
            "email_address": None,
            "domain": None,
            "allow_discovery": bool(allowDiscovery) if allowDiscovery is not None else False,
