        _log(endpoint, "OK", extra={"fileId": fileId, "permissionId": perm_id, "upsert": False})
        return {"permission": p}
    except Exception:
        _log(endpoint, "ERROR", "Unexpected error")
        return _err("CONFLICT", "Request could not be completed due to an internal conflict.")

def drive_file_list_comments(fileId, pageToken=None, pageSize=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _as_int(x):
        if isinstance(x, bool) or x is None:
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        if isinstance(x, (float, int)):
            try:
                return int(x)
            except Exception:
                return None
        if isinstance(x, str) and x.strip().isdigit():
            try:
                return int(x.strip())
            except Exception:
                return None
        return None

    def _get_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            return {"limits": {}, "quota": {}}
        limits = cfg.get("limits") or cfg.get("rate_limit") or {}
        quota = cfg.get("quota") or {}
        return {"limits": limits or {}, "quota": quota or {}}

    def _get_scope():
        items = _load("drive_items.json")
        if not isinstance(items, list):
            items = []
        owners = []
        for it in items:
            if isinstance(it, dict) and it.get("status") != "deleted":
                op = it.get("owner_principal")
                if isinstance(op, str) and op:
                    owners.append(op)
        if owners:
            owners.sort()
            return {"principal": owners[0]}
        return {"principal": None}

    def _has_access(principal, item, permissions_rows):
        if not isinstance(item, dict) or item.get("status") == "deleted":
            return False
        if principal and item.get("owner_principal") == principal:
            return True
        if item.get("shared_drive_id") is not None:
            return True
        iid = item.get("id")
        for p in permissions_rows:
            if not isinstance(p, dict):
                continue
            if p.get("status") != "active" or p.get("item_id") != iid:
                continue
            if p.get("role") in ("reader", "commenter", "writer", "organizer"):
                return True
        return False

    def _enforce_and_log(status_code, credential_used=None):
        cfg = _get_limits()
        limits = cfg["limits"]
        quota = cfg["quota"]
        rpm = _as_int(limits.get("requests_per_minute") or limits.get("requestsPerMinute"))
        rpd = _as_int(quota.get("requests_per_day") or quota.get("requestsPerDay") or limits.get("requests_per_day") or limits.get("requestsPerDay"))

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

        if isinstance(rpm, int) and rpm > 0:
            cutoff = now_utc - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpm:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_file_list_comments",
                        "status": "RATE_LIMIT",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("RATE_LIMIT", "Rate limit exceeded")

        if isinstance(rpd, int) and rpd > 0:
            cutoff = now_utc - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpd:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_file_list_comments",
                        "status": "QUOTA_EXCEEDED",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        latency_ms = int((time.time() - t0) * 1000)
        logs.append(
            {
                "timestamp": _now_iso(),
                "endpoint": "drive_file_list_comments",
                "status": status_code,
                "http_status": 200 if status_code == "OK" else 400,
                "latency_ms": latency_ms,
                "credential": credential_used,
            }
        )
        _save("request_logs.json", logs)
        return None

    if not isinstance(fileId, str) or not fileId.strip():
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "fileId must be a non-empty string")

    ps = _as_int(pageSize)
    if ps is None:
        ps = 50
    if ps <= 0 or ps > 200:
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "pageSize must be between 1 and 200")

    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    perms = _load("permissions.json")
    if not isinstance(perms, list):
        perms = []
    comments = _load("comments.json")
    if not isinstance(comments, list):
        comments = []

    item = None
    for it in items:
        if isinstance(it, dict) and it.get("id") == fileId and it.get("status") != "deleted":
            item = it
            break
    if item is None:
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "File not found")

    principal = _get_scope().get("principal")
    if not _has_access(principal, item, perms):
        e = _enforce_and_log("UNAUTHORIZED")
        if isinstance(e, dict):
            return e
        return _err("UNAUTHORIZED", "Not authorized to view comments")

    rows = []
    for c in comments:
        if not isinstance(c, dict):
            continue
        if c.get("status") != "active":
            continue
        if c.get("item_id") != fileId:
            continue
        if c.get("parent_comment_id") is not None:
            continue
        rows.append(c)

    # sort by created_at ascending
    def _k(r):
        ts = _parse_ts(r.get("created_at"))
        return ts or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    rows.sort(key=_k)

    start = 0
    if pageToken:
        if not isinstance(pageToken, str):
            e = _enforce_and_log("VALIDATION_ERROR")
            if isinstance(e, dict):
                return e
            return _err("VALIDATION_ERROR", "pageToken must be a string")
        try:
            start = int(pageToken)
            if start < 0:
                start = 0
        except Exception:
            # opaque tokens may be passed; treat as 0 rather than rejecting (relaxed)
            start = 0

    page = rows[start : start + ps]
    next_cursor = None
    if start + ps < len(rows):
        next_cursor = str(start + ps)

    e = _enforce_and_log("OK")
    if isinstance(e, dict):
        return e
    return {"comments": [dict(r) for r in page], "nextPageToken": next_cursor, "total": len(rows)}

