            break
    if item is None:
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "File not found")

    principal = _get_scope().get("principal")
    if not _has_manage_comments(principal, item, perms):
        e = _enforce_and_log("UNAUTHORIZED")
        if isinstance(e, dict):
            return e
        return _err("UNAUTHORIZED", "Not authorized to delete comments")

    target = None
    for c in comments:
        if isinstance(c, dict) and c.get("id") == commentId:
            target = c
            break
    if target is None or target.get("item_id") != fileId or target.get("parent_comment_id") is not None:
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "Comment not found on this file")

    if target.get("status") == "deleted":
        # idempotent
        e = _enforce_and_log("OK")
        if isinstance(e, dict):
            return e
        return {"deleted": True, "commentId": commentId}

    now = _now_iso()
    # Transition: active -> deleted, and cascade to replies
    affected = 0
    for c in comments:
        if not isinstance(c, dict):
            continue
        if c.get("id") == commentId or c.get("parent_comment_id") == commentId:
            if c.get("status") != "deleted":
                c["status"] = "deleted"
                c["updated_at"] = now
                affected += 1

    if affected == 0:
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "No matching active comment to delete")

    _save("comments.json", comments)

    e = _enforce_and_log("OK")
    if isinstance(e, dict):
        return e
    return {"deleted": True, "commentId": commentId, "affected": affected}

def drive_file_reply_to_comment(fileId, commentId, content, **_extra):
    import json, os, datetime, re, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + base64.b32encode(os.urandom(10)).decode("ascii").strip("=").lower(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = {}
        for fn in ("config.json", "drive_config.json", "service_config.json"):
            p = os.path.join(_DB, fn)
            if os.path.exists(p):
                try:
                    with open(p, encoding="utf-8") as f:
                        cfg = json.load(f) or {}
                except Exception:
                    cfg = {}
                break
        rl = cfg.get("rate_limit_per_minute")
        if rl is None:
            rl = cfg.get("rateLimitPerMinute")
        if rl is None:
            rl = 1200
        qd = cfg.get("quota_requests_per_day")
        if qd is None:
            qd = cfg.get("quotaRequestsPerDay")
        if qd is None:
            qd = 200000

        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            try:
                if isinstance(s, str) and s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        c1 = 0
        cday = 0
        for r in logs:
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                c1 += 1
            if ts >= day_ago:
                cday += 1

        if isinstance(rl, (int, float)) and rl >= 0 and c1 >= int(rl):
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(qd, (int, float)) and qd >= 0 and cday >= int(qd):
            return _err("QUOTA_EXCEEDED", "Request quota exceeded.")
        return None

    lim_err = _check_limits()
    if lim_err:
        _log("drive_file_reply_to_comment", "error", error_code=lim_err["error"]["code"])
        return lim_err

    if not isinstance(fileId, str) or not re.match(r"^gdrv_itm_[0-9A-HJKMNP-TV-Z]{20,}$", fileId):
        _log("drive_file_reply_to_comment", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fileId is malformed.")
    if not isinstance(commentId, str) or not re.match(r"^gdrv_cmt_[0-9A-HJKMNP-TV-Z]{20,}$", commentId):
        _log("drive_file_reply_to_comment", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "commentId is malformed.")
    if not isinstance(content, str) or not content.strip():
        _log("drive_file_reply_to_comment", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "content must be a non-empty string.")

    items = _load("drive_items.json")
    item = next((x for x in items if x.get("id") == fileId), None)
    if not item or item.get("status") == "deleted":
        _log("drive_file_reply_to_comment", "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "File not found.")
    if item.get("item_type") != "file":
        _log("drive_file_reply_to_comment", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Comments are only supported for files.")
    if item.get("status") != "active":
        _log("drive_file_reply_to_comment", "error", error_code="CONFLICT")
        return _err("CONFLICT", "File is not accepting comments in its current state.")

    comments = _load("comments.json")
    parent = next((c for c in comments if c.get("id") == commentId), None)
    if not parent:
        _log("drive_file_reply_to_comment", "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Parent comment not found.")
    if parent.get("item_id") != fileId:
        _log("drive_file_reply_to_comment", "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Parent comment does not belong to the specified file.")
    if parent.get("parent_comment_id") is not None:
        _log("drive_file_reply_to_comment", "error", error_code="CONFLICT")
        return _err("CONFLICT", "Cannot reply to a reply; commentId must be a top-level comment.")
    if parent.get("status") != "active":
        _log("drive_file_reply_to_comment", "error", error_code="CONFLICT")
        return _err("CONFLICT", "Comment thread is not accepting replies.")

    # Ambient authentication: pick a plausible acting principal.
    actor = item.get("modified_by_principal") or item.get("owner_principal") or "unknown"

    now = _now()
    new_id = "gdrv_cmt_" + base64.b32encode(os.urandom(16)).decode("ascii").strip("=").upper()
    reply = {
        "id": new_id,
        "item_id": fileId,
        "parent_comment_id": commentId,
        "author_principal": actor,
        "content": content,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    comments.append(reply)
    _save("comments.json", comments)
    _log("drive_file_reply_to_comment", "ok")
    return {"reply": reply}

def drive_file_list_replies(fileId, commentId, pageToken=None, pageSize=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _as_int(x):
        if isinstance(x, bool) or x is None:
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        if isinstance(x, (float, int)):
            try:
                return int(x)
            except Exception:
                return None
        if isinstance(x, str) and x.strip().isdigit():
            try:
                return int(x.strip())
            except Exception:
                return None
        return None

    def _get_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            return {"limits": {}, "quota": {}}
        limits = cfg.get("limits") or cfg.get("rate_limit") or {}
        quota = cfg.get("quota") or {}
        return {"limits": limits or {}, "quota": quota or {}}

    def _get_scope():
        items = _load("drive_items.json")
        if not isinstance(items, list):
            items = []
        owners = []
        for it in items:
            if isinstance(it, dict) and it.get("status") != "deleted":
                op = it.get("owner_principal")
                if isinstance(op, str) and op:
                    owners.append(op)
        if owners:
            owners.sort()
            return {"principal": owners[0]}
        return {"principal": None}

    def _has_access(principal, item, permissions_rows):
        if not isinstance(item, dict) or item.get("status") == "deleted":
            return False
        if principal and item.get("owner_principal") == principal:
            return True
        if item.get("shared_drive_id") is not None:
            return True
        iid = item.get("id")
        for p in permissions_rows:
            if not isinstance(p, dict):
                continue
            if p.get("status") != "active" or p.get("item_id") != iid:
                continue
            if p.get("role") in ("reader", "commenter", "writer", "organizer"):
                return True
        return False

    def _enforce_and_log(status_code, credential_used=None):
        cfg = _get_limits()
        limits = cfg["limits"]
        quota = cfg["quota"]
        rpm = _as_int(limits.get("requests_per_minute") or limits.get("requestsPerMinute"))
        rpd = _as_int(quota.get("requests_per_day") or quota.get("requestsPerDay") or limits.get("requests_per_day") or limits.get("requestsPerDay"))

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

        if isinstance(rpm, int) and rpm > 0:
            cutoff = now_utc - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpm:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_file_list_replies",
                        "status": "RATE_LIMIT",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("RATE_LIMIT", "Rate limit exceeded")

        if isinstance(rpd, int) and rpd > 0:
            cutoff = now_utc - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpd:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_file_list_replies",
                        "status": "QUOTA_EXCEEDED",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        latency_ms = int((time.time() - t0) * 1000)
        logs.append(
            {
                "timestamp": _now_iso(),
                "endpoint": "drive_file_list_replies",
                "status": status_code,
                "http_status": 200 if status_code == "OK" else 400,
                "latency_ms": latency_ms,
                "credential": credential_used,
            }
        )
        _save("request_logs.json", logs)
        return None

    if not isinstance(fileId, str) or not fileId.strip():
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "fileId must be a non-empty string")
    if not isinstance(commentId, str) or not commentId.strip():
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "commentId must be a non-empty string")

    ps = _as_int(pageSize)
    if ps is None:
        ps = 50
    if ps <= 0 or ps > 200:
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "pageSize must be between 1 and 200")

    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    perms = _load("permissions.json")
    if not isinstance(perms, list):
        perms = []
    comments = _load("comments.json")
    if not isinstance(comments, list):
        comments = []

    item = None
    for it in items:
        if isinstance(it, dict) and it.get("id") == fileId and it.get("status") != "deleted":
            item = it
            break
    if item is None:
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "File not found")

    principal = _get_scope().get("principal")
    if not _has_access(principal, item, perms):
        e = _enforce_and_log("UNAUTHORIZED")
        if isinstance(e, dict):
            return e
        return _err("UNAUTHORIZED", "Not authorized to view replies")

    parent = None
    for c in comments:
        if isinstance(c, dict) and c.get("id") == commentId:
            parent = c
            break
    if parent is None or parent.get("item_id") != fileId or parent.get("parent_comment_id") is not None:
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "Parent comment not found on this file")

    rows = []
    for c in comments:
        if not isinstance(c, dict):
            continue
        if c.get("status") != "active":
            continue
        if c.get("parent_comment_id") != commentId:
            continue
        rows.append(c)

    def _k(r):
        ts = _parse_ts(r.get("created_at"))
        return ts or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    rows.sort(key=_k)

    start = 0
    if pageToken:
        if not isinstance(pageToken, str):
            e = _enforce_and_log("VALIDATION_ERROR")
            if isinstance(e, dict):
                return e
            return _err("VALIDATION_ERROR", "pageToken must be a string")
        try:
            start = int(pageToken)
            if start < 0:
                start = 0
        except Exception:
            start = 0

    page = rows[start : start + ps]
    next_cursor = None
    if start + ps < len(rows):
        next_cursor = str(start + ps)

    e = _enforce_and_log("OK")
    if isinstance(e, dict):
        return e
    return {"replies": [dict(r) for r in page], "nextPageToken": next_cursor, "total": len(rows)}

