    def _log(endpoint, status, credential_used=None, error_code=None):
        logs = _load("request_log.json")
        row = {
            "id": f"rql_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        logs.append(row)
        _save("request_log.json", logs)

    pat_itm = re.compile(r"^gdrv_itm_[0-9A-Z]{18,}$")

    if not (isinstance(fileId, str) and pat_itm.match(fileId)):
        _log("drive_file_move", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fileId is malformed.")

    if addParents is None:
        addParents = []
    if removeParents is None:
        removeParents = []

    if not (isinstance(addParents, list) and all(isinstance(x, str) and pat_itm.match(x) for x in addParents)):
        _log("drive_file_move", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "addParents must be an array of folder IDs.")
    if not (isinstance(removeParents, list) and all(isinstance(x, str) and pat_itm.match(x) for x in removeParents)):
        _log("drive_file_move", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "removeParents must be an array of folder IDs.")

    # Disallow overlapping ids
    if set(addParents) & set(removeParents):
        _log("drive_file_move", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "addParents and removeParents must not overlap.")

    items = _load("drive_items.json")
    parents_rel = _load("drive_item_parents.json")

    item = next((r for r in items if r.get("id") == fileId and r.get("status") != "deleted"), None)
    if not item:
        _log("drive_file_move", "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "File not found.")

    # Locked rule: moving is a metadata mutation. Allow if unlocked OR there exists writer/organizer permission.
    if item.get("locked") is True:
        perms = _load("permissions.json")
        if not any(p.get("item_id") == fileId and p.get("status") == "active" and p.get("role") in ("writer", "organizer") for p in perms):
            _log("drive_file_move", "error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "File is locked and caller lacks sufficient permission to move it.")

    # Resolve folders; must be folders, not deleted, same shared_drive_id scope
    folder_ids = list(dict.fromkeys(addParents + removeParents))
    folders = {}
    for fid in folder_ids:
        frow = next((r for r in items if r.get("id") == fid and r.get("status") != "deleted"), None)
        if not frow:
            _log("drive_file_move", "error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", f"Parent folder not found: {fid}", parentId=fid)
        if frow.get("item_type") != "folder":
            _log("drive_file_move", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Parent must be a folder: {fid}", parentId=fid)
        if frow.get("shared_drive_id") != item.get("shared_drive_id"):
            _log("drive_file_move", "error", error_code="CONFLICT")
            return _err("CONFLICT", "Cannot move item across drive scopes (My Drive vs Shared Drive).", parentId=fid)
        folders[fid] = frow

    # Prevent cycles if item is a folder: cannot add a parent that is a descendant
    if item.get("item_type") == "folder" and addParents:
        # Build adjacency parent->children (active and not deleted children)
        child_by_parent = {}
        items_by_id = {r.get("id"): r for r in items}
        for rel in parents_rel:
            if rel.get("item_id") and rel.get("parent_folder_id"):
                child = items_by_id.get(rel.get("item_id"))
                if child and child.get("status") != "deleted":
                    child_by_parent.setdefault(rel.get("parent_folder_id"), set()).add(rel.get("item_id"))

        def _is_descendant(start_parent_id, target_item_id):
            # is target_item_id reachable under start_parent_id?
            seen = set()
            stack = [start_parent_id]
            while stack:
                p = stack.pop()
                if p in seen:
                    continue
                seen.add(p)
                for ch in child_by_parent.get(p, set()):
                    if ch == target_item_id:
                        return True
                    stack.append(ch)
            return False

        for new_parent in addParents:
            if _is_descendant(item.get("id"), new_parent):
                _log("drive_file_move", "error", error_code="CONFLICT")
                return _err("CONFLICT", "Cannot create a cycle in folder hierarchy.", parentId=new_parent)

    # Apply changes
    now = _now()
    changed = False

    # Helper: find existing relation
    def _find_rel(child_id, parent_id):
        for r in parents_rel:
            if r.get("item_id") == child_id and r.get("parent_folder_id") == parent_id:
                return r
        return None

    # Adds (idempotent)
    for pid in addParents:
        existing = _find_rel(fileId, pid)
        if existing is None:
            # create relation
            new_id = f"gdrv_prn_{int(time.time()*1000)}_{len(parents_rel)+1}"
            parents_rel.append({"id": new_id, "item_id": fileId, "parent_folder_id": pid, "created_at": now, "updated_at": now})
            changed = True

    # Removes
    if removeParents:
        before = len(parents_rel)
        parents_rel = [r for r in parents_rel if not (r.get("item_id") == fileId and r.get("parent_folder_id") in set(removeParents))]
        if len(parents_rel) != before:
            changed = True

    if not changed:
        _log("drive_file_move", "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No parent relations were changed (nothing to add/remove).")

    # Persist and update modified metadata timestamp
    _save("drive_item_parents.json", parents_rel)

    item["modified_at"] = now
    item["updated_at"] = now
    item["modified_by_principal"] = item.get("modified_by_principal") or item.get("owner_principal") or "unknown"
    _save("drive_items.json", items)

    # Return updated metadata including parents
    parent_ids = [r.get("parent_folder_id") for r in parents_rel if r.get("item_id") == fileId]
    _log("drive_file_move", "success")
    return {"file": item, "parents": parent_ids}

def drive_file_empty_trash(**_extra):
    import json, os, datetime, time

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_used=None, error_code=None):
        logs = _load("request_log.json")
        row = {
            "id": f"rql_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        logs.append(row)
        _save("request_log.json", logs)

    # Quota / rate limit based on request log: max 60 calls/min to this endpoint, max 500/day
    logs = _load("request_log.json")
    now_dt = datetime.datetime.utcnow()
    one_min_ago = now_dt - datetime.timedelta(minutes=1)
    one_day_ago = now_dt - datetime.timedelta(days=1)

    def _parse_ts(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s) if isinstance(s, str) else None
        except Exception:
            return None

    recent_1m = 0
    recent_1d = 0
    for r in logs:
        if r.get("endpoint") != "drive_file_empty_trash":
            continue
        ts = _parse_ts(r.get("timestamp"))
        if not ts:
            continue
        if ts >= one_min_ago:
            recent_1m += 1
        if ts >= one_day_ago:
            recent_1d += 1

    if recent_1m >= 60:
        _log("drive_file_empty_trash", "error", error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded for emptyTrash.")
    if recent_1d >= 500:
        _log("drive_file_empty_trash", "error", error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for emptyTrash.")

    items = _load("drive_items.json")
    parents_rel = _load("drive_item_parents.json")
    perms = _load("permissions.json")
    comments = _load("comments.json")
    versions = _load("file_versions.json")

    # Ambient auth: select a principal that can act. If there are any items at all, assume signed in.
    principals = {r.get("owner_principal") for r in items if r.get("owner_principal")}
    if not principals:
        _log("drive_file_empty_trash", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not signed in.")

    # Implementation: empty trash for all My Drive items per principal (since no explicit identity passed).
    # Choose a principal with at least one trashed item; else succeed with no-op? Real behavior returns success even if none,
    # but contract says no success without effect only for mutations that matched no row; here API is "empty trash"
    # and may legitimately delete zero items. We'll still return success with deleted_count=0.
    principal = None
    for p in principals:
        if any(r.get("owner_principal") == p and r.get("status") == "trashed" for r in items):
            principal = p
            break
    if principal is None:
        principal = next(iter(principals))

    trashed_ids = [r.get("id") for r in items if r.get("owner_principal") == principal and r.get("status") == "trashed"]

    # Permission gate: if locked items exist in trash without writer/organizer permission, forbid.
    # (Conservative interpretation of "not allowed to permanently delete one or more trashed items")
    if trashed_ids:
        perm_by_item = {}
        for p in perms:
            if p.get("status") == "active":
                perm_by_item.setdefault(p.get("item_id"), set()).add(p.get("role"))
        for iid in trashed_ids:
            it = next((r for r in items if r.get("id") == iid), None)
            if it and it.get("locked") is True:
                roles = perm_by_item.get(iid, set())
                if not (("writer" in roles) or ("organizer" in roles)):
                    _log("drive_file_empty_trash", "error", error_code="UNAUTHORIZED")
                    return _err("UNAUTHORIZED", "Not permitted to permanently delete one or more locked items in trash.", fileId=iid)

    now = _now()
    deleted_set = set(trashed_ids)

    # Mutate items: trashed->deleted
    changed = 0
    for r in items:
        if r.get("id") in deleted_set and r.get("status") == "trashed":
            r["status"] = "deleted"
            r["updated_at"] = now
            changed += 1

    # Cascade-ish cleanup (since JSON store doesn't enforce FK):
    if deleted_set:
        parents_rel = [r for r in parents_rel if r.get("item_id") not in deleted_set]
        perms = [r for r in perms if r.get("item_id") not in deleted_set]
        comments = [r for r in comments if r.get("item_id") not in deleted_set]
        versions = [r for r in versions if r.get("item_id") not in deleted_set]

    _save("drive_items.json", items)
    _save("drive_item_parents.json", parents_rel)
    _save("permissions.json", perms)
    _save("comments.json", comments)
    _save("file_versions.json", versions)

    _log("drive_file_empty_trash", "success")
    return {"status": "success", "deleted_count": changed}

def drive_shared_drives_list(pageSize=None, pageToken=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_used=None, error_code=None):
        logs = _load("request_log.json")
        row = {
            "id": f"rql_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        logs.append(row)
        _save("request_log.json", logs)

    # Validate pageSize
    if pageSize is None:
        pageSize = 50
    if not (isinstance(pageSize, (int, float)) and int(pageSize) == pageSize):
        _log("drive_shared_drives_list", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "pageSize must be an integer.")
    pageSize = int(pageSize)
    if pageSize < 1 or pageSize > 100:
        _log("drive_shared_drives_list", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "pageSize out of range (1..100).")

    # Parse pageToken (opaque; derived from (created_at,id))
    start_created_at = None
    start_id = None
    if pageToken is not None:
        if not isinstance(pageToken, str) or pageToken.strip() == "":
            _log("drive_shared_drives_list", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "pageToken is malformed.")
        try:
            raw = base64.urlsafe_b64decode(pageToken.encode("utf-8") + b"===").decode("utf-8")
            # format: created_at|id
            parts = raw.split("|", 1)
            if len(parts) != 2:
                raise ValueError("bad token")
            start_created_at, start_id = parts[0], parts[1]
            # validate iso-ish
            if not start_created_at or not start_id:
                raise ValueError("bad token")
        except Exception:
            _log("drive_shared_drives_list", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "pageToken is malformed.")

    shared_drives = _load("shared_drives.json")
    items = _load("drive_items.json")

    # Ambient auth: require there exists at least one principal in the dataset
    principals = {r.get("owner_principal") for r in items if r.get("owner_principal")}
    principals |= {r.get("created_by_principal") for r in shared_drives if r.get("created_by_principal")}
    principals.discard(None)
    if not principals:
        _log("drive_shared_drives_list", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not signed in.")

    # Choose a principal with access: created_by_principal matches (simple model per schema/index)
    principal = None
    for p in principals:
        if any(d.get("status") == "active" and d.get("created_by_principal") == p for d in shared_drives):
            principal = p
            break
    if principal is None:
        principal = next(iter(principals))

    rows = [d for d in shared_drives if d.get("status") == "active" and d.get("created_by_principal") == principal]

    # Sort by (created_at, id)
    def _key(d):
        return (d.get("created_at") or "", d.get("id") or "")
    rows.sort(key=_key)

    # Apply cursor
    if start_created_at is not None:
        rows = [d for d in rows if _key(d) > (start_created_at, start_id)]

    total = len(rows)
    page = rows[:pageSize]
    has_more = total > pageSize

    nextPageToken = None
    if has_more and page:
        last = page[-1]
        token_raw = f"{last.get('created_at') or ''}|{last.get('id') or ''}"
        nextPageToken = base64.urlsafe_b64encode(token_raw.encode("utf-8")).decode("utf-8").rstrip("=")

    _log("drive_shared_drives_list", "success")
    return {
        "sharedDrives": page,
        "nextPageToken": nextPageToken,
        "pageSize": pageSize,
        "totalAccessible": total,
    }

def drive_shared_drive_get(driveId, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, drive_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "service": "google_drive",
            "endpoint": "drive_shared_drive_get",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
            "drive_id": drive_id,
            "error_code": error_code
        })
        _save("request_logs.json", logs)

    # Validation
    if driveId is None or not isinstance(driveId, str) or not driveId.strip():
        _log("error", drive_id=driveId, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "driveId is required and must be a non-empty string.")
    driveId = driveId.strip()

    # Ambient auth: best-effort resolve caller principal; if absent, treat as unauthorized.
    ctx = _load("auth_context.json")
    principal = None
    if isinstance(ctx, dict):
        principal = ctx.get("principal") or ctx.get("email") or ctx.get("user")
    if not principal:
        _log("error", drive_id=driveId, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not signed in.")

    shared_drives = _load("shared_drives.json")
    if not isinstance(shared_drives, list):
        shared_drives = []

    row = next((d for d in shared_drives if isinstance(d, dict) and d.get("id") == driveId and d.get("status") == "active"), None)

    # Visibility: creator can see; otherwise require membership/permission model not present => not visible.
    if not row or row.get("created_by_principal") != principal:
        _log("error", drive_id=driveId, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Shared Drive not found or not visible to caller.", driveId=driveId)

    _log("ok", drive_id=driveId)
    return {"sharedDrive": row}

def drive_shared_drive_create(name, colorRgb=None, hidden=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, drive_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "service": "google_drive",
            "endpoint": "drive_shared_drive_create",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
            "drive_id": drive_id,
            "error_code": error_code
        })
        _save("request_logs.json", logs)

    # Validation
    if name is None or not isinstance(name, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must be a string.")
    name = name.strip()
    if not name:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be non-empty.")
    if colorRgb is not None:
        if not isinstance(colorRgb, str):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "colorRgb must be a string when provided.")
        if not re.fullmatch(r"#?[0-9A-Fa-f]{6}", colorRgb.strip()):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "colorRgb must match /^#?[0-9A-Fa-f]{6}$/.")

    if hidden is not None and not isinstance(hidden, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "hidden must be a boolean when provided.")

    # Ambient auth
    ctx = _load("auth_context.json")
    principal = None
    if isinstance(ctx, dict):
        principal = ctx.get("principal") or ctx.get("email") or ctx.get("user")
    if not principal:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not signed in.")

    # Quota: limit shared drives per principal
    cfg = _load("config.json")
    if not isinstance(cfg, dict):
        cfg = {}
    limit = cfg.get("shared_drive_create_limit_per_principal", 50)
    try:
        limit = int(limit)
    except Exception:
        limit = 50

    shared_drives = _load("shared_drives.json")
    if not isinstance(shared_drives, list):
        shared_drives = []

    active_count = 0
    for d in shared_drives:
        if isinstance(d, dict) and d.get("created_by_principal") == principal and d.get("status") == "active":
            active_count += 1
    if active_count >= limit:
        _log("error", error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Shared Drive creation quota exceeded.", limit=limit, used=active_count)

    # Unique(created_by_principal, name) where status='active'
    for d in shared_drives:
        if isinstance(d, dict) and d.get("status") == "active" and d.get("created_by_principal") == principal and d.get("name") == name:
            _log("error", error_code="CONFLICT")
            return _err("CONFLICT", "An active Shared Drive with this name already exists for the caller.", name=name)

    drive_id = "drv_" + uuid.uuid4().hex
    row = {
        "id": drive_id,
        "name": name,
        "color_rgb": (colorRgb.strip() if isinstance(colorRgb, str) else None),
        "hidden": (hidden if hidden is not None else False),
        "status": "active",
        "created_by_principal": principal,
        "created_at": now,
        "updated_at": now
    }
    shared_drives.append(row)
    _save("shared_drives.json", shared_drives)

    _log("ok", drive_id=drive_id)
    return {"sharedDrive": row}

