    if name is not None:
        if not isinstance(name, str):
            _log("error", drive_id=driveId, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be a string when provided.")
        if not name.strip():
            _log("error", drive_id=driveId, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be non-empty when provided.")
        name = name.strip()

    if colorRgb is not None:
        if not isinstance(colorRgb, str):
            _log("error", drive_id=driveId, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "colorRgb must be a string when provided.")
        if not re.fullmatch(r"#?[0-9A-Fa-f]{6}", colorRgb.strip()):
            _log("error", drive_id=driveId, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "colorRgb must match /^#?[0-9A-Fa-f]{6}$/.")

    if hidden is not None and not isinstance(hidden, bool):
        _log("error", drive_id=driveId, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "hidden must be a boolean when provided.")

    if name is None and colorRgb is None and hidden is None:
        _log("error", drive_id=driveId, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one field (name, colorRgb, hidden) must be provided to update.")

    # Ambient auth
    ctx = _load("auth_context.json")
    principal = None
    if isinstance(ctx, dict):
        principal = ctx.get("principal") or ctx.get("email") or ctx.get("user")
    if not principal:
        _log("error", drive_id=driveId, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not signed in.")

    shared_drives = _load("shared_drives.json")
    if not isinstance(shared_drives, list):
        shared_drives = []

    idx = None
    row = None
    for i, d in enumerate(shared_drives):
        if isinstance(d, dict) and d.get("id") == driveId:
            idx, row = i, d
            break

    if not row or row.get("status") != "active" or row.get("created_by_principal") != principal:
        _log("error", drive_id=driveId, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Shared Drive not found or not visible to caller.", driveId=driveId)

    # Cannot update deleted
    if row.get("status") != "active":
        _log("error", drive_id=driveId, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot update a deleted Shared Drive.", status=row.get("status"))

    # Uniqueness constraint if name changes
    if name is not None and name != row.get("name"):
        for d in shared_drives:
            if isinstance(d, dict) and d.get("status") == "active" and d.get("created_by_principal") == principal and d.get("name") == name and d.get("id") != driveId:
                _log("error", drive_id=driveId, error_code="CONFLICT")
                return _err("CONFLICT", "An active Shared Drive with this name already exists for the caller.", name=name)

    changed = False
    if name is not None and name != row.get("name"):
        row["name"] = name
        changed = True
    if colorRgb is not None:
        newc = colorRgb.strip()
        if newc != row.get("color_rgb"):
            row["color_rgb"] = newc
            changed = True
    if hidden is not None and hidden != row.get("hidden"):
        row["hidden"] = hidden
        changed = True

    if not changed:
        # No success without effect (idempotent update with same values): return current resource (real APIs often do).
        # But contract says mutation with no matched row must not succeed; here row matched. It's safe to return.
        row["updated_at"] = row.get("updated_at") or now
        shared_drives[idx] = row
        _save("shared_drives.json", shared_drives)
        _log("ok", drive_id=driveId)
        return {"sharedDrive": row}

    row["updated_at"] = now
    shared_drives[idx] = row
    _save("shared_drives.json", shared_drives)

    _log("ok", drive_id=driveId)
    return {"sharedDrive": row}

def drive_shared_drive_files(driveId, pageSize=None, pageToken=None, q=None, orderBy=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "drive_shared_drive_files"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if isinstance(s, str):
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1]
            try:
                return datetime.datetime.fromisoformat(ss)
            except ValueError:
                return None
        return None

    def _log(status, credential_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{hashlib.md5((endpoint+_now_iso()).encode('utf-8')).hexdigest()[:8]}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso()
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    # Quota/Rate limiting (best-effort, based on request_logs if present)
    def _enforce_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rate = cfg.get("rate_limit_per_minute", 600)
        quota = cfg.get("daily_quota_requests", 20000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        c1 = 0
        cday = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                c1 += 1
            if ts >= day_ago:
                cday += 1
        if isinstance(rate, int) and rate >= 0 and c1 >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(quota, int) and quota >= 0 and cday >= quota:
            return _err("QUOTA_EXCEEDED", "Request quota exceeded.")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", extra={"error_code": lim_err["error"]["code"]})
        return lim_err

    # Validate
    if not isinstance(driveId, str) or not driveId.strip():
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "driveId must be a non-empty string.")
    driveId = driveId.strip()

    if pageSize is None:
        pageSize_i = 100
    else:
        if not isinstance(pageSize, (int, float)) or isinstance(pageSize, bool):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "pageSize must be a number.")
        pageSize_i = int(pageSize)
        if pageSize_i <= 0 or pageSize_i > 1000:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "pageSize out of range (1..1000).")

    if pageToken is not None and (not isinstance(pageToken, str) or not pageToken.strip()):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "pageToken must be a non-empty string when provided.")

    if q is not None and not isinstance(q, str):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "q must be a string when provided.")

    if orderBy is not None and not isinstance(orderBy, str):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "orderBy must be a string when provided.")

    # Ambient auth: select a principal that can access this shared drive (created_by_principal)
    shared_drives = _load("shared_drives.json")
    if not isinstance(shared_drives, list):
        shared_drives = []
    drive = next((d for d in shared_drives if d.get("id") == driveId and d.get("status") == "active"), None)
    if not drive:
        _log("error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Shared drive not found or not accessible.", driveId=driveId)

    caller_principal = drive.get("created_by_principal")
    if not caller_principal:
        # If store is incomplete, treat as unauthorized rather than allowing anonymous access.
        _log("error", extra={"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Not signed in.")

    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []

    # Filter by drive + not deleted
    rows = [it for it in items if it.get("shared_drive_id") == driveId and it.get("status") != "deleted"]

    # Apply optional q (simple fulltext over name/description)
    if q:
        term = q.strip().lower()
        if term:
            def _text(it):
                return ((it.get("name") or "") + " " + (it.get("description") or "")).lower()
            rows = [it for it in rows if term in _text(it)]

    # OrderBy support
    def _key_name(it):
        return (it.get("name") or "").lower(), (it.get("id") or "")
    def _key_modified_desc(it):
        dt = _parse_dt(it.get("modified_at")) or datetime.datetime(1970, 1, 1)
        return (-dt.timestamp(), it.get("id") or "")
    def _key_created_desc(it):
        dt = _parse_dt(it.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (-dt.timestamp(), it.get("id") or "")

    sort_key = None
    reverse = False
    ob = (orderBy or "").strip()

    if not ob or ob in ("name", "name asc"):
        sort_key = _key_name
        reverse = False
        ob_norm = "name asc"
    elif ob in ("name desc",):
        sort_key = _key_name
        reverse = True
        ob_norm = "name desc"
    elif ob in ("modifiedTime desc", "modified_at desc", "modifiedTimeDesc", "modified desc"):
        sort_key = _key_modified_desc
        reverse = False
        ob_norm = "modifiedTime desc"
    elif ob in ("createdTime desc", "created_at desc"):
        sort_key = _key_created_desc
        reverse = False
        ob_norm = "createdTime desc"
    else:
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unsupported orderBy.", allowed=["name", "name desc", "modifiedTime desc", "createdTime desc"])

    rows.sort(key=sort_key, reverse=reverse)

    # Pagination token is an opaque cursor: "v1:<offset>:<hash>"
    offset = 0
    if pageToken:
        pt = pageToken.strip()
        m = re.match(r"^v1:(\d+):([0-9a-f]{8})$", pt)
        if not m:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid pageToken.")
        offset = int(m.group(1))
        # hash binds token to query parameters lightly
        tok_hash = m.group(2)
        bind = hashlib.md5((driveId + "|" + (q or "") + "|" + ob_norm).encode("utf-8")).hexdigest()[:8]
        if tok_hash != bind:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "pageToken does not match this query.")
        if offset < 0 or offset > len(rows):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "pageToken offset out of range.")

    total = len(rows)
    page = rows[offset: offset + pageSize_i]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_token = None
    if has_more:
        bind = hashlib.md5((driveId + "|" + (q or "") + "|" + ob_norm).encode("utf-8")).hexdigest()[:8]
        next_token = f"v1:{next_offset}:{bind}"

    _log("ok", extra={"driveId": driveId, "result_count": len(page)})
    return {
        "driveId": driveId,
        "files": page,
        "pageSize": pageSize_i,
        "nextPageToken": next_token,
        "hasMore": has_more,
        "total": total
    }

