        _log("error", extra={"error_code": lim_err["error"]["code"]})
        return lim_err

    if maxResults is None:
        max_n = 20
    else:
        if not isinstance(maxResults, (int, float)) or isinstance(maxResults, bool):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "maxResults must be a number.")
        max_n = int(maxResults)
        if max_n < 1 or max_n > 1000:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "maxResults out of range (1..1000).")

    # Ambient auth
    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    principals = sorted({it.get("owner_principal") for it in items if isinstance(it.get("owner_principal"), str) and it.get("owner_principal").strip()})
    if not principals:
        _log("error", extra={"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Not signed in.")
    caller_principal = principals[0]

    agg = {}
    for it in items:
        if it.get("status") != "active":
            continue
        if it.get("owner_principal") != caller_principal:
            continue
        if it.get("item_type") != "file":
            continue
        mt = it.get("mime_type") or "application/octet-stream"
        sb = it.get("size_bytes")
        if not isinstance(sb, int) or sb < 0:
            continue
        agg[mt] = agg.get(mt, 0) + sb

    rows = [{"mimeType": k, "usedBytes": v} for k, v in agg.items()]
    rows.sort(key=lambda r: (-r["usedBytes"], r["mimeType"]))
    rows = rows[:max_n]

    _log("ok", extra={"principal": caller_principal, "types": len(rows)})
    return {
        "principal": caller_principal,
        "maxResults": max_n,
        "breakdown": rows
    }

def drive_batch_get_metadata(fileIds, fields=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "drive_batch_get_metadata"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if isinstance(s, str):
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1]
            try:
                return datetime.datetime.fromisoformat(ss)
            except ValueError:
                return None
        return None

    def _log(status, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{hashlib.md5((endpoint+_now_iso()).encode('utf-8')).hexdigest()[:8]}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso()
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(batch_size):
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rate = cfg.get("rate_limit_per_minute", 600)
        quota = cfg.get("daily_quota_requests", 20000)
        max_batch = cfg.get("batch_get_metadata_max_ids", 500)
        if not isinstance(max_batch, int) or max_batch <= 0:
            max_batch = 500
        if batch_size > max_batch:
            return _err("QUOTA_EXCEEDED", "Batch size exceeds allowed limit.", maxAllowed=max_batch)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        c1 = 0
        cday = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                c1 += 1
            if ts >= day_ago:
                cday += 1
        if isinstance(rate, int) and rate >= 0 and c1 >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(quota, int) and quota >= 0 and cday >= quota:
            return _err("QUOTA_EXCEEDED", "Request quota exceeded.")
        return None

    # Validate fileIds
    if not isinstance(fileIds, list):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "fileIds must be an array of strings.")
    if len(fileIds) == 0:
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "fileIds must not be empty.")
    for fid in fileIds:
        if not isinstance(fid, str) or not fid.strip():
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Each fileId must be a non-empty string.")

    # Validate fields (projection)
    projection = None
    if fields is not None:
        if not isinstance(fields, str):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "fields must be a string when provided.")
        fs = [f.strip() for f in fields.split(",") if f.strip()]
        if not fs:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "fields is malformed (no fields).")
        # allow simple identifiers and nested dot paths
        bad = [f for f in fs if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)*$", f)]
        if bad:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "fields is malformed.", invalid=bad)
        projection = fs

    lim_err = _enforce_limits(len(fileIds))
    if lim_err:
        _log("error", extra={"error_code": lim_err["error"]["code"]})
        return lim_err

    # Ambient auth: choose a principal; used to decide visibility (simplified: owner or shared drive creator or explicit permission)
    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    perms = _load("permissions.json")
    if not isinstance(perms, list):
        perms = []
    drives = _load("shared_drives.json")
    if not isinstance(drives, list):
        drives = []

    principals = sorted({it.get("owner_principal") for it in items if isinstance(it.get("owner_principal"), str) and it.get("owner_principal").strip()})
    if not principals:
        _log("error", extra={"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Not signed in.")
    caller_principal = principals[0]

    drive_creator = {d.get("id"): d.get("created_by_principal") for d in drives if d.get("status") == "active"}

    perms_by_item = {}
    for p in perms:
        if p.get("status") != "active":
            continue
        iid = p.get("item_id")
        if not iid:
            continue
        perms_by_item.setdefault(iid, []).append(p)

    def _accessible(it):
        if it.get("status") == "deleted":
            return False
        if it.get("owner_principal") == caller_principal:
            return True
        sd = it.get("shared_drive_id")
        if sd and drive_creator.get(sd) == caller_principal:
            return True
        # Permissions: allow if there is any active permission to this principal email (user/group) or anyone/domain (best-effort)
        plist = perms_by_item.get(it.get("id"), [])
        for p in plist:
            t = p.get("type")
            if t in ("anyone", "domain"):
                return True
            if t in ("user", "group") and p.get("email_address") == caller_principal:
                return True
        return False

    def _project(obj, fields_list):
        if fields_list is None:
            return obj
        out = {}
        for f in fields_list:
            # dot-path projection
            cur = obj
            ok = True
            parts = f.split(".")
            for part in parts:
                if not isinstance(cur, dict) or part not in cur:
                    ok = False
                    break
                cur = cur.get(part)
            if not ok:
                continue
            # assign into out nested
            tgt = out
            for part in parts[:-1]:
                if part not in tgt or not isinstance(tgt[part], dict):
                    tgt[part] = {}
                tgt = tgt[part]
            tgt[parts[-1]] = cur
        # Always include id if present for correlation, matching typical batch semantics
        if "id" in obj and "id" not in out:
            out["id"] = obj["id"]
        return out

    items_by_id = {it.get("id"): it for it in items if isinstance(it.get("id"), str)}

    results = []
    for fid in fileIds:
        fid = fid.strip()
        it = items_by_id.get(fid)
        if not it or it.get("status") == "deleted":
            results.append({"fileId": fid, "error": {"code": "NOT_FOUND", "message": "File not found."}})
            continue
        if not _accessible(it):
            results.append({"fileId": fid, "error": {"code": "NOT_FOUND", "message": "File not found."}})
            continue
        results.append({"fileId": fid, "metadata": _project(it, projection)})

    _log("ok", extra={"principal": caller_principal, "requested": len(fileIds)})
    return {
        "principal": caller_principal,
        "results": results,
        "fields": fields
    }

def drive_batch_update_permissions(operations, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "drive_batch_update_permissions",
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)

    if not isinstance(operations, list) or len(operations) == 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "operations must be a non-empty array")

    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    perms = _load("permissions.json")
    if not isinstance(perms, list):
        perms = []

    items_by_id = {it.get("id"): it for it in items if isinstance(it, dict) and isinstance(it.get("id"), str)}

    def _find_active_perm(item_id, ptype, email, domain):
        for p in perms:
            if not isinstance(p, dict):
                continue
            if p.get("status") != "active":
                continue
            if p.get("item_id") != item_id:
                continue
            if p.get("type") != ptype:
                continue
            if (p.get("email_address") or None) != (email or None):
                continue
            if (p.get("domain") or None) != (domain or None):
                continue
            return p
        return None

    results = []
    changed = False

    for op_idx, op in enumerate(operations):
        if not isinstance(op, dict):
            results.append({"index": op_idx, "ok": False, "error": _err("VALIDATION_ERROR", "operation must be an object")["error"]})
            continue
        fid = op.get("fileId")
        pd = op.get("permissionDetails")
        if not isinstance(fid, str) or not fid.strip():
            results.append({"index": op_idx, "ok": False, "error": _err("VALIDATION_ERROR", "fileId is required")["error"]})
            continue
        if not isinstance(pd, dict):
            results.append({"index": op_idx, "ok": False, "error": _err("VALIDATION_ERROR", "permissionDetails is required")["error"]})
            continue
        role = pd.get("role")
        ptype = pd.get("type")
        email = pd.get("emailAddress")
        domain = pd.get("domain")

        if role not in ("reader", "commenter", "writer", "organizer"):
            results.append({"index": op_idx, "ok": False, "error": _err("VALIDATION_ERROR", "permissionDetails.role is invalid")["error"]})
            continue
        if ptype not in ("user", "group", "domain", "anyone"):
            results.append({"index": op_idx, "ok": False, "error": _err("VALIDATION_ERROR", "permissionDetails.type is invalid")["error"]})
            continue

        it = items_by_id.get(fid)
        if not it or it.get("status") == "deleted":
            results.append({"index": op_idx, "ok": False, "error": _err("NOT_FOUND", "File not found")["error"]})
            continue

        # type constraints
        if ptype in ("user", "group"):
            if not isinstance(email, str) or not email.strip() or domain is not None:
                results.append({"index": op_idx, "ok": False, "error": _err("VALIDATION_ERROR", "emailAddress is required for user/group and domain must be null")["error"]})
                continue
            email = email.strip()
            domain = None
        elif ptype == "domain":
            if not isinstance(domain, str) or not domain.strip() or email is not None:
                results.append({"index": op_idx, "ok": False, "error": _err("VALIDATION_ERROR", "domain is required for domain type and emailAddress must be null")["error"]})
                continue
            domain = domain.strip()
            email = None
        else:  # anyone
            if email is not None or domain is not None:
                results.append({"index": op_idx, "ok": False, "error": _err("VALIDATION_ERROR", "emailAddress/domain must be null for anyone type")["error"]})
                continue
            email = None
            domain = None

        if role == "organizer" and it.get("shared_drive_id") is None:
            results.append({"index": op_idx, "ok": False, "error": _err("VALIDATION_ERROR", "cannot grant organizer unless item is in a shared drive")["error"]})
            continue

        # Upsert: update existing active permission or create new active, avoiding duplicates
        existing = _find_active_perm(fid, ptype, email, domain)
        if existing is not None:
            # update role if different
            if existing.get("role") != role:
                existing["role"] = role
                existing["updated_at"] = now
                changed = True
            results.append({"index": op_idx, "ok": True, "permission": existing})
            continue

        # create
        pid = "gdrv_perm_" + secrets.token_hex(12)
        created_by = it.get("modified_by_principal") or it.get("owner_principal") or "principal_unknown"
        row = {
            "id": pid,
            "item_id": fid,
            "type": ptype,
            "role": role,
            "email_address": email,
            "domain": domain,
            "allow_discovery": True if ptype in ("anyone", "domain") else False,
            "status": "active",
            "created_by_principal": created_by,
            "created_at": now,
            "updated_at": now
        }
        perms.append(row)
        changed = True
        results.append({"index": op_idx, "ok": True, "permission": row})

    if changed:
        _save("permissions.json", perms)

    _log("success", None)
    return {"results": results}

def drive_batch_delete(fileIds, permanent=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, extra=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "rl_" + uuid.uuid4().hex,
                "endpoint": "drive_batch_delete",
                "credential_used": None,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "extra": extra or {}
            })
            _save("request_logs.json", logs)

    def _enforce_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            return None
        limits = cfg.get("limits") or {}
        rpm = limits.get("requests_per_minute")
        rpd = limits.get("requests_per_day")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None

        def _parse_ts(s):
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        if isinstance(rpm, int) and rpm > 0:
            cutoff = now_dt - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp", ""))
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(rpd, int) and rpd > 0:
            cutoff = now_dt - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp", ""))
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpd:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        return None

    lim = _enforce_limits()
    if lim:
        _log("error", extra={"error": lim["error"]})
        return lim

    if not isinstance(fileIds, list) or len(fileIds) == 0 or any((not isinstance(x, str) or not x) for x in fileIds):
        e = _err("VALIDATION_ERROR", "fileIds must be a non-empty array of non-empty strings")
        _log("error", extra={"error": e["error"]})
        return e
    if len(set(fileIds)) != len(fileIds):
        e = _err("VALIDATION_ERROR", "fileIds must not contain duplicates")
        _log("error", extra={"error": e["error"]})
        return e
    if permanent is None:
        permanent = False
    if not isinstance(permanent, bool):
        e = _err("VALIDATION_ERROR", "permanent must be a boolean")
        _log("error", extra={"error": e["error"]})
        return e

    drive_items = _load("drive_items.json")
    parents = _load("drive_item_parents.json")
    permissions = _load("permissions.json")
    comments = _load("comments.json")
    versions = _load("file_versions.json")
    shared_drives = _load("shared_drives.json")

    if not all(isinstance(x, list) for x in [drive_items, parents, permissions, comments, versions, shared_drives]):
        e = _err("CONFLICT", "Datastore is not in expected format")
        _log("error", extra={"error": e["error"]})
        return e

    items_by_id = {r.get("id"): r for r in drive_items if isinstance(r, dict) and isinstance(r.get("id"), str)}
    shared_by_id = {r.get("id"): r for r in shared_drives if isinstance(r, dict) and isinstance(r.get("id"), str)}

    # Ambient principal for mutation: use owner of first found item; else any owner.
    principal = None
    for fid in fileIds:
        it = items_by_id.get(fid)
        if it and it.get("status") != "deleted" and isinstance(it.get("owner_principal"), str):
            principal = it["owner_principal"]
            break
    if principal is None:
        for it in drive_items:
            if isinstance(it, dict) and it.get("status") != "deleted" and isinstance(it.get("owner_principal"), str):
                principal = it["owner_principal"]
                break
    if principal is None:
        e = _err("UNAUTHORIZED", "Not signed in")
        _log("error", extra={"error": e["error"]})
        return e

    def _is_item_accessible(item):
        if not item or item.get("status") == "deleted":
            return False
        if item.get("shared_drive_id"):
            sd = shared_by_id.get(item.get("shared_drive_id"))
            return bool(sd and sd.get("status") == "active")
        return item.get("owner_principal") == principal

    def _has_delete_rights(item):
        if item.get("owner_principal") == principal:
            return True
        # writer/organizer permission
        iid = item.get("id")
        for p in permissions:
            if not isinstance(p, dict):
                continue
            if p.get("item_id") != iid or p.get("status") != "active":
                continue
            if p.get("role") in ["writer", "organizer"]:
                if p.get("type") in ["user", "group"] and p.get("email_address") == principal:
                    return True
                if p.get("type") in ["domain", "anyone"]:
                    return True
        return False

    results = []
    changed_items = False
    changed_parents = False
    changed_perms = False
    changed_comments = False
    changed_versions = False

    # Pre-index for cascades by item id
    parents_list = parents
    perms_list = permissions
    comments_list = comments
    versions_list = versions

    for fid in fileIds:
        item = items_by_id.get(fid)
        if not item or item.get("status") == "deleted":
            results.append({"fileId": fid, "success": False, "error": {"code": "NOT_FOUND", "message": "File not found"}})
            continue
        if not _is_item_accessible(item):
            results.append({"fileId": fid, "success": False, "error": {"code": "NOT_FOUND", "message": "File not found"}})
            continue
        if not _has_delete_rights(item):
            results.append({"fileId": fid, "success": False, "error": {"code": "UNAUTHORIZED", "message": "Insufficient permission to delete"}})
            continue

        # locked rule: delete/trash allowed with writer/organizer; we already require delete rights; owner ok.
        if item.get("locked") is True and not _has_delete_rights(item):
            results.append({"fileId": fid, "success": False, "error": {"code": "UNAUTHORIZED", "message": "Item is locked"}})
            continue

        if not permanent:
            if item.get("status") == "active":
                item["status"] = "trashed"
                item["trashed_at"] = now
                item["modified_by_principal"] = principal
                item["modified_at"] = now
                item["updated_at"] = now
                changed_items = True
                results.append({"fileId": fid, "success": True, "status": "trashed"})
            elif item.get("status") == "trashed":
                # idempotent
                if not item.get("trashed_at"):
                    item["trashed_at"] = now
                    item["updated_at"] = now
                    changed_items = True
                results.append({"fileId": fid, "success": True, "status": "trashed"})
            else:
                results.append({"fileId": fid, "success": False, "error": {"code": "INVALID_TRANSITION", "message": "Item cannot be trashed from current state"}})
        else:
            if item.get("status") in ["active", "trashed"]:
                item["status"] = "deleted"
                item["updated_at"] = now
                # enforce deleted => excluded; clear trash timestamp
                item["trashed_at"] = item.get("trashed_at") if item.get("trashed_at") else None
                changed_items = True

                # cascade delete: remove parent links, revoke permissions, delete comments, delete versions
                before = len(parents_list)
                parents_list = [r for r in parents_list if not (isinstance(r, dict) and r.get("item_id") == fid)]
                if len(parents_list) != before:
                    changed_parents = True

                # permissions: since lifecycle exists, transition to revoked
                any_perm_changed = False
                for p in perms_list:
                    if isinstance(p, dict) and p.get("item_id") == fid and p.get("status") == "active":
                        p["status"] = "revoked"
                        p["updated_at"] = now
                        any_perm_changed = True
                if any_perm_changed:
                    changed_perms = True

                # comments: transition to deleted
                any_com_changed = False
                for c in comments_list:
                    if isinstance(c, dict) and c.get("item_id") == fid and c.get("status") == "active":
                        c["status"] = "deleted"
                        c["updated_at"] = now
                        any_com_changed = True
                if any_com_changed:
                    changed_comments = True

                # versions: transition to deleted
                any_ver_changed = False
                for v in versions_list:
                    if isinstance(v, dict) and v.get("item_id") == fid and v.get("status") == "active":
                        v["status"] = "deleted"
                        v["updated_at"] = now
                        any_ver_changed = True
                if any_ver_changed:
                    changed_versions = True

                results.append({"fileId": fid, "success": True, "status": "deleted"})
            elif item.get("status") == "deleted":
                results.append({"fileId": fid, "success": True, "status": "deleted"})
            else:
                results.append({"fileId": fid, "success": False, "error": {"code": "INVALID_TRANSITION", "message": "Item cannot be deleted from current state"}})

    if changed_items:
        _save("drive_items.json", drive_items)
    if changed_parents:
        _save("drive_item_parents.json", parents_list)
        parents = parents_list
    if changed_perms:
        _save("permissions.json", perms_list)
        permissions = perms_list
    if changed_comments:
        _save("comments.json", comments_list)
        comments = comments_list
    if changed_versions:
        _save("file_versions.json", versions_list)
        versions = versions_list

    body = {
        "results": results,
        "metadata": {
            "permanent": permanent,
            "operation_count": len(fileIds),
            "success_count": sum(1 for r in results if r.get("success") is True),
            "failure_count": sum(1 for r in results if r.get("success") is False),
        }
    }
    _log("ok", extra={"success": body["metadata"]["success_count"], "failure": body["metadata"]["failure_count"], "permanent": permanent})
    return body

def drive_batch_move(operations, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, extra=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "rl_" + uuid.uuid4().hex,
                "endpoint": "drive_batch_move",
                "credential_used": None,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "extra": extra or {}
            })
            _save("request_logs.json", logs)

    def _enforce_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            return None
        limits = cfg.get("limits") or {}
        rpm = limits.get("requests_per_minute")
        rpd = limits.get("requests_per_day")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None

        def _parse_ts(s):
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        if isinstance(rpm, int) and rpm > 0:
            cutoff = now_dt - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp", ""))
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(rpd, int) and rpd > 0:
            cutoff = now_dt - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp", ""))
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpd:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        return None

    lim = _enforce_limits()
    if lim:
        _log("error", extra={"error": lim["error"]})
        return lim

    if not isinstance(operations, list) or len(operations) == 0:
        e = _err("VALIDATION_ERROR", "operations must be a non-empty array")
        _log("error", extra={"error": e["error"]})
        return e

    drive_items = _load("drive_items.json")
    parents = _load("drive_item_parents.json")
    permissions = _load("permissions.json")
    shared_drives = _load("shared_drives.json")

    if not all(isinstance(x, list) for x in [drive_items, parents, permissions, shared_drives]):
        e = _err("CONFLICT", "Datastore is not in expected format")
        _log("error", extra={"error": e["error"]})
        return e

    items_by_id = {r.get("id"): r for r in drive_items if isinstance(r, dict) and isinstance(r.get("id"), str)}
    shared_by_id = {r.get("id"): r for r in shared_drives if isinstance(r, dict) and isinstance(r.get("id"), str)}

    # Ambient principal
    principal = None
    for op in operations:
        if isinstance(op, dict) and isinstance(op.get("fileId"), str):
            it = items_by_id.get(op["fileId"])
            if it and it.get("status") != "deleted" and isinstance(it.get("owner_principal"), str):
                principal = it["owner_principal"]
                break
    if principal is None:
        for it in drive_items:
            if isinstance(it, dict) and it.get("status") != "deleted" and isinstance(it.get("owner_principal"), str):
                principal = it["owner_principal"]
                break
    if principal is None:
        e = _err("UNAUTHORIZED", "Not signed in")
        _log("error", extra={"error": e["error"]})
        return e

    def _is_item_accessible(item):
        if not item or item.get("status") == "deleted":
            return False
        if item.get("shared_drive_id"):
            sd = shared_by_id.get(item.get("shared_drive_id"))
            return bool(sd and sd.get("status") == "active")
        return item.get("owner_principal") == principal

    def _has_writer_or_organizer(item):
        if item.get("owner_principal") == principal:
            return True
        iid = item.get("id")
        for p in permissions:
            if not isinstance(p, dict):
                continue
            if p.get("item_id") != iid or p.get("status") != "active":
                continue
            if p.get("role") in ["writer", "organizer"]:
                if p.get("type") in ["user", "group"] and p.get("email_address") == principal:
                    return True
                if p.get("type") in ["domain", "anyone"]:
                    return True
        return False

    def _new_id(prefix):
        import uuid as _uuid
        return prefix + "_" + _uuid.uuid4().hex

    # Cycle prevention: destination cannot be a descendant of item when moving folders
    parent_map = {}
    for rel in parents:
        if isinstance(rel, dict):
            cid = rel.get("item_id")
            pid = rel.get("parent_folder_id")
            if isinstance(cid, str) and isinstance(pid, str):
                parent_map.setdefault(cid, set()).add(pid)

    def _is_descendant(ancestor_id, possible_desc_id):
        # is possible_desc_id in subtree of ancestor_id?
        # build children map for traversal
        children = {}
        for rel in parents:
            if isinstance(rel, dict):
                cid = rel.get("item_id")
                pid = rel.get("parent_folder_id")
                if isinstance(cid, str) and isinstance(pid, str):
                    children.setdefault(pid, set()).add(cid)
        seen = set()
        stack = [ancestor_id]
        while stack:
            cur = stack.pop()
            if cur in seen:
                continue
            seen.add(cur)
            for ch in children.get(cur, ()):
                if ch == possible_desc_id:
                    return True
                stack.append(ch)
        return False

    def _validate_folder(folder_id):
        fol = items_by_id.get(folder_id)
        if not fol or fol.get("status") == "deleted" or not _is_item_accessible(fol):
            return None, _err("NOT_FOUND", "Destination folder not found")
        if fol.get("item_type") != "folder":
            return None, _err("VALIDATION_ERROR", "destinationFolderId must be a folder")
        return fol, None

    results = []
    changed_items = False
    changed_parents = False

    for op in operations:
        if not isinstance(op, dict):
            results.append({"success": False, "error": {"code": "VALIDATION_ERROR", "message": "Each operation must be an object"}})
            continue
        if set(op.keys()) - {"fileId", "destinationFolderId", "removeFromCurrentFolders"}:
            results.append({"success": False, "error": {"code": "VALIDATION_ERROR", "message": "Unexpected fields in operation"}})
            continue
        fid = op.get("fileId")
        dfid = op.get("destinationFolderId")
        if not isinstance(fid, str) or not fid or not isinstance(dfid, str) or not dfid:
            results.append({"success": False, "error": {"code": "VALIDATION_ERROR", "message": "fileId and destinationFolderId are required"}})
            continue
        remove_flag = op.get("removeFromCurrentFolders")
        if remove_flag is None:
            remove_flag = True
        if not isinstance(remove_flag, bool):
            results.append({"fileId": fid, "success": False, "error": {"code": "VALIDATION_ERROR", "message": "removeFromCurrentFolders must be boolean"}})
            continue

        item = items_by_id.get(fid)
        if not item or item.get("status") == "deleted" or not _is_item_accessible(item):
            results.append({"fileId": fid, "success": False, "error": {"code": "NOT_FOUND", "message": "File not found"}})
            continue

        dest_folder, derr = _validate_folder(dfid)
        if derr:
            results.append({"fileId": fid, "success": False, "error": derr["error"]})
            continue

        # same drive scope
        if (item.get("shared_drive_id") or None) != (dest_folder.get("shared_drive_id") or None):
            results.append({"fileId": fid, "success": False, "error": {"code": "CONFLICT", "message": "Destination folder is in a different drive scope"}})
            continue

        # locked: moving is a metadata mutation
        if item.get("locked") is True and not _has_writer_or_organizer(item):
            results.append({"fileId": fid, "success": False, "error": {"code": "UNAUTHORIZED", "message": "Item is locked"}})
            continue

        # Need writer/organizer to move
        if not _has_writer_or_organizer(item):
            results.append({"fileId": fid, "success": False, "error": {"code": "UNAUTHORIZED", "message": "Insufficient permission to move"}})
            continue

        # cycle prevention for folders
        if item.get("item_type") == "folder":
            if fid == dfid or _is_descendant(fid, dfid):
                results.append({"fileId": fid, "success": False, "error": {"code": "CONFLICT", "message": "Move would create a cycle"}})
                continue

        # ensure parent relation exists to destination (unique(item_id,parent_folder_id))
        exists = False
        for rel in parents:
            if isinstance(rel, dict) and rel.get("item_id") == fid and rel.get("parent_folder_id") == dfid:
                exists = True
                break
        if not exists:
            parents.append({
                "id": _new_id("par"),
                "item_id": fid,
                "parent_folder_id": dfid,
                "created_at": now,
                "updated_at": now
            })
            changed_parents = True

        if remove_flag:
            before = len(parents)
            parents = [r for r in parents if not (isinstance(r, dict) and r.get("item_id") == fid and r.get("parent_folder_id") != dfid)]
            if len(parents) != before:
                changed_parents = True

        # update modified timestamps (metadata change)
        item["modified_by_principal"] = principal
        item["modified_at"] = now
        item["updated_at"] = now
        changed_items = True

        results.append({"fileId": fid, "success": True, "movedFile": item})

    if changed_items:
        _save("drive_items.json", drive_items)
    if changed_parents:
        _save("drive_item_parents.json", parents)

    body = {
        "results": results,
        "metadata": {
            "operation_count": len(operations),
            "success_count": sum(1 for r in results if r.get("success") is True),
            "failure_count": sum(1 for r in results if r.get("success") is False),
        }
    }
    _log("ok", extra={"success": body["metadata"]["success_count"], "failure": body["metadata"]["failure_count"]})
    return body

def drive_update(fileId, name=None, description=None, starred=None, locked=None, status=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Quota / rate-limit via request log (best-effort; if collection absent, still create it)
    def _log(status_code, credential_id=None, error=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rl_{int(time.time() * 1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "drive_update",
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error,
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save("request_logs.json", logs)

    def _check_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rate = cfg.get("rate_limit", {}).get("requests_per_minute", 0)
        daily = cfg.get("quota", {}).get("requests_per_day", 0)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        # compute windows
        try:
            ts_now = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
        except Exception:
            return None
        if isinstance(rate, int) and rate > 0:
            cutoff = ts_now - datetime.timedelta(seconds=60)
            c = 0
            for r in logs:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    d = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if d >= cutoff:
                    c += 1
            if c >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(daily, int) and daily > 0:
            cutoff = ts_now - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    d = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if d >= cutoff:
                    c += 1
            if c >= daily:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    lim = _check_limits()
    if lim:
        _log(429, error=lim["error"]["code"])
        return lim

    # Validate inputs
    if not isinstance(fileId, str) or not fileId:
        _log(400, error="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fileId must be a non-empty string")
    if name is not None and (not isinstance(name, str) or name.strip() == ""):
        _log(400, error="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")
    if description is not None and not isinstance(description, str):
        _log(400, error="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string when provided")
    if starred is not None and not isinstance(starred, bool):
        _log(400, error="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "starred must be a boolean when provided")
    if locked is not None and not isinstance(locked, bool):
        _log(400, error="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "locked must be a boolean when provided")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "trashed", "deleted"):
            _log(400, error="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, trashed, deleted")

    drive_items = _load("drive_items.json")
    if not isinstance(drive_items, list):
        drive_items = []
    item = None
    for r in drive_items:
        if isinstance(r, dict) and r.get("id") == fileId:
            item = r
            break
    if not item or item.get("status") == "deleted":
        _log(404, error="NOT_FOUND")
        return _err("NOT_FOUND", "File not found")

    # Enforce lock restrictions (no explicit caller context available; treat as unauthorized for mutating ops)
    if item.get("locked") is True:
        # Changing any metadata or lifecycle is a mutation
        if any(v is not None for v in (name, description, starred, locked, status)):
            _log(401, error="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Item is locked and cannot be modified with current credentials")

    changed = False
    # Metadata updates
    if name is not None and name != item.get("name"):
        item["name"] = name
        changed = True
    if description is not None and description != item.get("description"):
        item["description"] = description
        changed = True
    if starred is not None and starred != item.get("starred"):
        item["starred"] = starred
        changed = True
    if locked is not None and locked != item.get("locked"):
        item["locked"] = locked
        changed = True

    # Lifecycle transitions
    if status is not None and status != item.get("status"):
        cur = item.get("status")
        allowed = {
            "active": {"trashed", "deleted"},
            "trashed": {"active", "deleted"},
            "deleted": set()
        }
        if cur not in allowed or status not in allowed[cur]:
            _log(409, error="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Illegal status transition from {cur} to {status}")
        # Apply transition semantics
        if status == "trashed":
            item["status"] = "trashed"
            item["trashed_at"] = now
        elif status == "active":
            item["status"] = "active"
            item["trashed_at"] = None
        elif status == "deleted":
            item["status"] = "deleted"
            item["trashed_at"] = item.get("trashed_at")  # keep as-is if present
            # Cascade-like cleanup per business rules
            parents = _load("drive_item_parents.json")
            if not isinstance(parents, list):
                parents = []
            new_parents = [p for p in parents if not (isinstance(p, dict) and p.get("item_id") == fileId)]
            if len(new_parents) != len(parents):
                _save("drive_item_parents.json", new_parents)

            perms = _load("permissions.json")
            if not isinstance(perms, list):
                perms = []
            new_perms = [p for p in perms if not (isinstance(p, dict) and p.get("item_id") == fileId)]
            if len(new_perms) != len(perms):
                _save("permissions.json", new_perms)

            comments = _load("comments.json")
            if not isinstance(comments, list):
                comments = []
            new_comments = [c for c in comments if not (isinstance(c, dict) and c.get("item_id") == fileId)]
            if len(new_comments) != len(comments):
                _save("comments.json", new_comments)

        changed = True

    if not changed:
        _log(200)
        return {"item": item}

    # Update audit timestamps
    item["modified_by_principal"] = item.get("modified_by_principal") or item.get("owner_principal") or "unknown"
    item["modified_at"] = now
    item["updated_at"] = now

    _save("drive_items.json", drive_items)
    _log(200)
    return {"item": item}

