            return _err("VALIDATION_ERROR", "emailAddress is required for type=user/group")
        if domain is not None:
            _log(400, error="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "domain must be null for type=user/group")
    elif type == "domain":
        if not isinstance(domain, str) or domain.strip() == "":
            _log(400, error="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "domain is required for type=domain")
        if emailAddress is not None:
            _log(400, error="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "emailAddress must be null for type=domain")
    elif type == "anyone":
        if emailAddress is not None or domain is not None:
            _log(400, error="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "emailAddress/domain must be null for type=anyone")

    drive_items = _load("drive_items.json")
    if not isinstance(drive_items, list):
        drive_items = []
    item = None
    for r in drive_items:
        if isinstance(r, dict) and r.get("id") == fileId:
            item = r
            break
    if not item or item.get("status") == "deleted":
        _log(404, error="NOT_FOUND")
        return _err("NOT_FOUND", "File not found")

    # Restriction: organizer only for shared drive items
    if role == "organizer" and not item.get("shared_drive_id"):
        _log(409, error="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Cannot grant organizer unless item is in a shared drive")

    # If item is locked, treat sharing changes as unauthorized (no caller context)
    if item.get("locked") is True:
        _log(401, error="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Item is locked and sharing cannot be modified with current credentials")

    permissions = _load("permissions.json")
    if not isinstance(permissions, list):
        permissions = []

    # Upsert active permission by unique key (item_id, type, email/domain)
    def _key(p):
        return (
            p.get("item_id"),
            p.get("type"),
            (p.get("email_address") or ""),
            (p.get("domain") or "")
        )

    want_email = emailAddress if type in ("user", "group") else None
    want_domain = domain if type == "domain" else None
    want_discovery = bool(allowDiscovery) if allowDiscovery is not None else False

    existing = None
    for p in permissions:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "active":
            continue
        if _key(p) == (fileId, type, want_email or "", want_domain or ""):
            existing = p
            break

    if existing:
        # Update fields idempotently
        changed = False
        if existing.get("role") != role:
            existing["role"] = role
            changed = True
        if existing.get("allow_discovery") != want_discovery:
            existing["allow_discovery"] = want_discovery
            changed = True
        if changed:
            existing["updated_at"] = now
            _save("permissions.json", permissions)
        _log(200)
        return {"permission": existing}

    # Create new permission
    # Generate id convention
    new_id = f"perm_{int(time.time() * 1000)}_{os.getpid()}_{len(permissions)+1}"
    created_by = item.get("modified_by_principal") or item.get("owner_principal") or "unknown"
    newp = {
        "id": new_id,
        "item_id": fileId,
        "type": type,
        "role": role,
        "email_address": want_email,
        "domain": want_domain,
        "allow_discovery": want_discovery,
        "status": "active",
        "created_by_principal": created_by,
        "created_at": now,
        "updated_at": now
    }
    permissions.append(newp)
    _save("permissions.json", permissions)
    _log(200)
    return {"permission": newp}

def drive_comment_create(fileId, content, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0029000" if __import__("os").path.isdir("./environment_mix/0029000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _as_int(x):
        if isinstance(x, bool) or x is None:
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        if isinstance(x, str) and x.isdigit():
            try:
                return int(x)
            except Exception:
                return None
        return None

    def _get_limits():
        cfg = _load("config.json")
        if not isinstance(cfg, dict):
            return {"limits": {}, "quota": {}}
        limits = cfg.get("limits") or cfg.get("rate_limit") or {}
        quota = cfg.get("quota") or {}
        return {"limits": limits or {}, "quota": quota or {}}

    def _get_scope():
        items = _load("drive_items.json")
        if not isinstance(items, list):
            items = []
        owners = []
        for it in items:
            if isinstance(it, dict) and it.get("status") != "deleted":
                op = it.get("owner_principal")
                if isinstance(op, str) and op:
                    owners.append(op)
        if owners:
            owners.sort()
            return {"principal": owners[0]}
        return {"principal": None}

    def _has_comment_access(principal, item, permissions_rows):
        if not isinstance(item, dict) or item.get("status") == "deleted":
            return False
        if principal and item.get("owner_principal") == principal:
            return True
        if item.get("shared_drive_id") is not None:
            return True
        iid = item.get("id")
        for p in permissions_rows:
            if not isinstance(p, dict):
                continue
            if p.get("status") != "active" or p.get("item_id") != iid:
                continue
            if p.get("role") in ("commenter", "writer", "organizer"):
                return True
        return False

    def _enforce_and_log(status_code, credential_used=None):
        cfg = _get_limits()
        limits = cfg["limits"]
        quota = cfg["quota"]
        rpm = _as_int(limits.get("requests_per_minute") or limits.get("requestsPerMinute"))
        rpd = _as_int(quota.get("requests_per_day") or quota.get("requestsPerDay") or limits.get("requests_per_day") or limits.get("requestsPerDay"))

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

        if isinstance(rpm, int) and rpm > 0:
            cutoff = now_utc - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpm:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_comment_create",
                        "status": "RATE_LIMIT",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("RATE_LIMIT", "Rate limit exceeded")

        if isinstance(rpd, int) and rpd > 0:
            cutoff = now_utc - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _parse_ts((r or {}).get("timestamp"))
                if ts and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts and ts >= cutoff:
                    c += 1
            if c >= rpd:
                latency_ms = int((time.time() - t0) * 1000)
                logs.append(
                    {
                        "timestamp": _now_iso(),
                        "endpoint": "drive_comment_create",
                        "status": "QUOTA_EXCEEDED",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        "credential": credential_used,
                    }
                )
                _save("request_logs.json", logs)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        latency_ms = int((time.time() - t0) * 1000)
        logs.append(
            {
                "timestamp": _now_iso(),
                "endpoint": "drive_comment_create",
                "status": status_code,
                "http_status": 200 if status_code == "OK" else 400,
                "latency_ms": latency_ms,
                "credential": credential_used,
            }
        )
        _save("request_logs.json", logs)
        return None

    if not isinstance(fileId, str) or not fileId.strip():
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "fileId must be a non-empty string")
    if not isinstance(content, str) or not content.strip():
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "content must be a non-empty string")

    items = _load("drive_items.json")
    if not isinstance(items, list):
        items = []
    perms = _load("permissions.json")
    if not isinstance(perms, list):
        perms = []
    comments = _load("comments.json")
    if not isinstance(comments, list):
        comments = []

    item = None
    for it in items:
        if isinstance(it, dict) and it.get("id") == fileId and it.get("status") != "deleted":
            item = it
            break
    if item is None:
        e = _enforce_and_log("NOT_FOUND")
        if isinstance(e, dict):
            return e
        return _err("NOT_FOUND", "File not found")

    if item.get("item_type") != "file":
        e = _enforce_and_log("VALIDATION_ERROR")
        if isinstance(e, dict):
            return e
        return _err("VALIDATION_ERROR", "FAILED_PRECONDITION: comments allowed only on files")
    if item.get("status") != "active":
        e = _enforce_and_log("INVALID_TRANSITION")
        if isinstance(e, dict):
            return e
        return _err("INVALID_TRANSITION", "FAILED_PRECONDITION: cannot comment on non-active item")

    principal = _get_scope().get("principal") or (item.get("owner_principal") or "user:unknown")

    if not _has_comment_access(principal, item, perms):
        e = _enforce_and_log("UNAUTHORIZED")
        if isinstance(e, dict):
            return e
        return _err("UNAUTHORIZED", "Not authorized to comment")

    now = _now_iso()
    cmt_id = "gdrv_cmt_" + secrets.token_hex(12)
    row = {
        "id": cmt_id,
        "item_id": fileId,
        "parent_comment_id": None,
        "author_principal": principal,
        "content": content,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    comments.append(row)
    _save("comments.json", comments)

    e = _enforce_and_log("OK")
    if isinstance(e, dict):
        return e
    return {"comment": dict(row)}
